INSERT INTO public.master_plan_capability_library (code, payload, criteria, source_sha256)
VALUES
  ('T01', $${"code":"T01","nature":"Transversal","title":"Gestão de Informações e Acervo","summary":"Organizar, registrar, nomear, guardar e recuperar informações, planilhas e acervo documental (interno e do cliente), garantindo versão correta, rastreabilidade e acesso a quem precisa.","originLabel":"Transversal (origem: Gestão Interna)","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de organizar, registrar, nomear, guardar e recuperar informações, planilhas e acervo documental da Ramos e dos clientes, garantindo que a versão correta esteja disponível, rastreável e acessível a quem precisa, no momento em que precisa.","scope":"• aplicar a estrutura de pastas e a regra de nomenclatura da Ramos\r\n• controlar versões (minuta, vigente, substituída)\r\n• manter planilhas de controle íntegras e atualizadas\r\n• organizar e guardar o acervo do cliente (licenças, outorgas, protocolos, certidões)\r\n• localizar rapidamente documentos e informações solicitados\r\n• registrar origem e data das informações\r\n• controlar acesso e confidencialidade","performanceCriteria":"• Localização rápida: qualquer documento ou informação sob sua guarda é encontrado em poucos minutos, sem depender da memória de quem arquivou. Como se comprova: o avaliador pede de surpresa documentos de clientes diferentes (licença, protocolo, certidão) e cronometra a localização.\r\n• Versão correta: o que está identificado como vigente é de fato a versão em vigor; minutas e versões substituídas ficam marcadas ou arquivadas à parte. Como se comprova: conferência de uma amostra de pastas, verificando se há duplicidade ou versão antiga circulando como atual.\r\n• Padrão de pastas e nomenclatura: os arquivos seguem a estrutura e a regra de nomes da Ramos, de modo que outra pessoa consegue navegar sem ajuda. Como se comprova: um colega que não conhece o acervo localiza um documento seguindo apenas a estrutura.\r\n• Controles atualizados: planilhas e registros de controle não têm lacunas, campos vazios ou informações vencidas. Como se comprova: comparação de uma amostra do controle com os documentos reais do acervo.\r\n• Integridade do acervo: nenhum documento foi perdido, apagado ou sobrescrito no período avaliado. Como se comprova: verificação do histórico de pastas e de ocorrências registradas.","assisted":"Consegue: arquivar e nomear documentos no padrão e atualizar planilhas existentes.\r\nAinda necessita: conferência periódica da organização e orientação em casos fora do padrão (classificação duvidosa, versões conflitantes).","autonomous":"Faz sozinho: organiza o acervo completo de clientes, mantém os controles, resolve conflitos de versão e atende pedidos de informação.\r\nDecide: onde classificar documentos novos, qual versão é a vigente e quem pode acessar.","multiplier":"Audita a organização de outros colaboradores, define e melhora a estrutura de pastas e a nomenclatura, treina a equipe e corrige desvios recorrentes.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 2 pastas ou acervos de clientes organizados por você no padrão Ramos.\r\nComo é avaliado: um Autônomo percorre as pastas, confere nomenclatura, versões e completude e pede a localização de 5 documentos.\r\nAprovado quando: não há desvio relevante de padrão e os 5 documentos são localizados na versão correta.\r\n\r\nAUTÔNOMO\r\nO que entregar: o acervo completo sob sua guarda, em uso real há pelo menos 2 meses.\r\nComo é avaliado: auditoria por amostragem — o avaliador sorteia 10 documentos e pede que sejam localizados na hora, verificando também se a versão é a vigente e se o controle está atualizado.\r\nAprovado quando: os 10 documentos são localizados rapidamente, todos na versão correta, e o controle não apresenta lacunas.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) relatório da auditoria que você conduziu no acervo de outro colaborador; (2) registro de um treinamento ministrado sobre organização do acervo; (3) uma melhoria na estrutura ou na nomenclatura implantada.\r\nComo é avaliado: a direção ou outro Multiplicador analisa o relatório, conversa com quem foi treinado e verifica se a melhoria está em uso.\r\nAprovado quando: a auditoria identificou desvios reais, o colaborador treinado aplica o padrão e a melhoria foi adotada pela equipe.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T02 Uso e Integridade do SISRAMOS — Assistido.\r\nMultiplicador: Autônomo nesta capacidade há 6 meses.","limits":"Não abrange a elaboração do conteúdo técnico dos documentos nem a política de TI/segurança da informação. Não autoriza alterar documentos oficiais emitidos por órgãos ou pelo cliente.","relatedCapabilitiesText":"T02 Uso e Integridade do SISRAMOS · F05 Gestão Documental Regulatória · F11 Gestão de Dados e Evidências de Campo"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você entende a estrutura de pastas, a regra de nomenclatura e o controle de versões da Ramos e sabe onde cada tipo de documento do cliente deve ficar?","sourceRef":"Autoavaliação!A5:E5"},{"number":2,"dimension":"Execução","question":"Você consegue organizar, nomear, guardar e localizar documentos e manter as planilhas de controle atualizadas no dia a dia?","sourceRef":"Autoavaliação!A6:E6"},{"number":3,"dimension":"Julgamento e decisão","question":"Diante de um documento sem classificação clara ou de versões conflitantes, você consegue decidir onde guardar e qual é a versão vigente?","sourceRef":"Autoavaliação!A7:E7"},{"number":4,"dimension":"Qualidade e consistência","question":"Os documentos sob sua guarda são encontrados rapidamente, sem duplicidade nem versão obsoleta circulando como vigente?","sourceRef":"Autoavaliação!A8:E8"}],"sourceRefs":["Catálogo de Capacidades!A5:D5","Fichas de Capacidade!A5:P5"]}$$::jsonb, $$[{"id":"T01-AS-01","level":1,"text":"Arquiva e nomeia no padrão Ramos","kind":"evidence","guidance":"Amostra de arquivos salvos pela pessoa: local, nome e versão.","reviewCheck":"Nomes seguem a regra; arquivos no local previsto; sem duplicidade criada por ela.","supportingEvidence":"Pastas indicadas; histórico de alteração dos arquivos.","insufficientEvidence":"Arquivos que foram reorganizados por outra pessoa depois.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"Peça para localizar, na hora, um documento que ela arquivou.","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-AS-02","level":1,"text":"Mantém controles atualizados","kind":"evidence","guidance":"Planilhas de controle que a pessoa alimenta comparadas aos documentos reais.","reviewCheck":"Registros completos, datas corretas, sem campo em branco nos itens sob sua atualização.","supportingEvidence":"Planilha de controle e documentos correspondentes.","insufficientEvidence":"Planilha preenchida apenas em parte ou com dados copiados sem conferência.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-AS-03","level":1,"text":"Reconhece casos fora do padrão","kind":"evidence","guidance":"Se a pessoa identifica e leva adiante dúvidas de classificação ou de versão, em vez de improvisar.","reviewCheck":"Relata situações em que pediu orientação; não criou pastas ou versões paralelas.","supportingEvidence":"Mensagens/e-mails pedindo orientação; relato do responsável pelo acervo.","insufficientEvidence":"Ausência de dúvidas pode indicar que não percebe o problema — confirme com amostra.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-AU-01","level":2,"text":"Localiza rapidamente na versão correta","kind":"evidence","guidance":"Sorteio de documentos de clientes diferentes sob sua guarda.","reviewCheck":"Documentos encontrados sem hesitação, todos na versão vigente.","supportingEvidence":"Acervo real; controle de versões.","insufficientEvidence":"Localizar apenas documentos escolhidos pela própria pessoa.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de documentos sorteados: A definir (a ficha v1.0 previa 10).","reviewQuestion":"Peça um documento de um cliente que ela não atende com frequência.","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-AU-02","level":2,"text":"Decide classificação e versão com fundamento","kind":"evidence","guidance":"Casos de classificação duvidosa e conflitos de versão resolvidos pela pessoa.","reviewCheck":"Explica o critério usado; minutas e substituídas estão marcadas ou separadas.","supportingEvidence":"Histórico de versões; relato do caso.","insufficientEvidence":"Ausência de conflitos no período (pode indicar pouco volume).","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-AU-03","level":2,"text":"Mantém controles íntegros e sem lacunas","kind":"evidence","guidance":"Comparação de amostra do controle com os documentos reais.","reviewCheck":"Sem campos vazios, sem informação vencida, datas e origens registradas.","supportingEvidence":"Planilha de controle; documentos do acervo.","insufficientEvidence":"Controle atualizado só na véspera da avaliação.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-AU-04","level":2,"text":"Protege informação sensível","kind":"evidence","guidance":"Guarda de senhas, certificados e documentos confidenciais.","reviewCheck":"Acesso restrito a quem precisa; nada exposto em pastas abertas ou e-mails.","supportingEvidence":"Controle de acessos; estrutura de guarda.","insufficientEvidence":"Declaração de que 'ninguém mexe' sem verificação.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-MU-01","level":3,"text":"Audita acervos de outros com resultado","kind":"evidence","guidance":"Registro de auditoria em acervo de terceiros.","reviewCheck":"Desvios reais identificados, classificados por gravidade e corrigidos ou encaminhados.","supportingEvidence":"Relatório de auditoria; pastas antes/depois.","insufficientEvidence":"Auditoria sem achados ou sem providência.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"Peça um desvio encontrado e confira se foi corrigido.","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-MU-02","level":3,"text":"Forma pessoas no padrão de organização","kind":"evidence","guidance":"Colegas orientados pela pessoa.","reviewCheck":"Os orientados arquivam e localizam no padrão sem depender dela.","supportingEvidence":"Registro de orientação/treinamento; amostra do acervo dos orientados.","insufficientEvidence":"Lista de presença de treinamento.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T01-MU-03","level":3,"text":"Melhora a estrutura ou a regra","kind":"evidence","guidance":"Melhoria de pastas, nomenclatura ou versões proposta/implantada.","reviewCheck":"Melhoria justificada por problema real, aprovada quando necessário e em uso.","supportingEvidence":"Proposta registrada; estrutura vigente.","insufficientEvidence":"Ideia não implantada ou usada só pela própria pessoa.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T02', $${"code":"T02","nature":"Transversal","title":"Uso e Integridade do SISRAMOS","summary":"Registrar demandas, cards e lançamentos corretamente no SISRAMOS, manter status atualizados, auditar inconsistências e interpretar os painéis (Radar Vital) para apoiar decisões.","originLabel":"Transversal (origem: Gestão Interna)","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de registrar demandas, cards e lançamentos corretamente no SISRAMOS, manter status, responsáveis e prazos fiéis à realidade, identificar e corrigir inconsistências e interpretar os painéis (Radar Vital) para apoiar decisões de gestão.","scope":"• registrar demandas, cards e lançamentos com todos os campos obrigatórios\r\n• vincular cliente, setor, responsável e prazo corretos\r\n• atualizar o status a cada mudança de etapa\r\n• registrar a passagem de bastão no sistema\r\n• auditar lançamentos e apontar inconsistências (sem dono, sem prazo, parados)\r\n• ler e interpretar os painéis e o Radar Vital\r\n• reportar falhas e sugerir melhorias ao sistema","performanceCriteria":"• Registros completos e coerentes: cada card ou lançamento tem cliente, setor, responsável, prazo e descrição preenchidos de forma que outra pessoa entenda do que se trata. Como se comprova: sorteio de registros feitos pela pessoa e conferência campo a campo.\r\n• Status fiel à realidade: o status no SISRAMOS corresponde ao que está acontecendo de fato; não existem demandas concluídas como abertas, nem paradas como em andamento. Como se comprova: comparação de uma amostra de cards com a situação real confirmada com o responsável.\r\n• Tratamento de inconsistências: ao auditar, a pessoa não só aponta o problema, mas corrige o que está na sua alçada e aciona o responsável pelo restante. Como se comprova: leitura do relatório de auditoria e verificação de que os itens foram resolvidos.\r\n• Leitura dos painéis: a pessoa sabe explicar o que um painel ou o Radar Vital está mostrando e qual ação aquilo pede. Como se comprova: o avaliador apresenta um painel real e pede a interpretação e a ação recomendada.\r\n• Informação confiável para decidir: a gestão consegue tomar decisões com base nos registros da pessoa sem precisar de conferência paralela. Como se comprova: consulta aos gestores que usam aqueles dados.","assisted":"Consegue: registrar e atualizar os próprios cards e lançamentos.\r\nAinda necessita: conferência dos registros e orientação em casos atípicos.","autonomous":"Faz sozinho: mantém íntegros os registros da sua área, audita lançamentos de outros e interpreta painéis.\r\nDecide: corrigir inconsistências, reclassificar registros e acionar responsáveis.","multiplier":"Define regras de uso, treina usuários, conduz auditorias gerais de integridade, interpreta o Radar Vital para a gestão e propõe melhorias ao SISRAMOS/BI.","certificationEvidence":"ASSISTIDO\r\nO que entregar: nada além do trabalho normal — o avaliador seleciona 20 registros feitos por você no último mês.\r\nComo é avaliado: conferência campo a campo e comparação com a situação real das demandas.\r\nAprovado quando: nenhum dos 20 registros tem erro crítico (responsável, cliente ou prazo errado, status falso).\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) relatório de uma auditoria feita por você em uma carteira ou setor, listando as inconsistências encontradas e o que foi corrigido; (2) leitura comentada de um painel real.\r\nComo é avaliado: o avaliador confere uma amostra das inconsistências e das correções e conversa sobre a interpretação do painel.\r\nAprovado quando: as inconsistências apontadas eram reais, as correções foram feitas ou encaminhadas e a leitura do painel leva a uma ação coerente.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) registro de treinamento de usuários; (2) auditoria geral do sistema; (3) uma regra de uso ou melhoria aprovada.\r\nComo é avaliado: a direção analisa o material e verifica, um mês depois, se a qualidade dos registros dos treinados melhorou.\r\nAprovado quando: a regra ou melhoria está em vigor e os registros dos usuários treinados apresentam menos erros.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T01 Gestão de Informações e Acervo — Assistido.\r\nMultiplicador: T08 Análise e Resolução de Problemas — Autônomo.","limits":"Não abrange desenvolvimento ou programação do SISRAMOS/BI (Tecnologia e Sistemas). Não autoriza alterar registros de outros setores sem comunicar o responsável.","relatedCapabilitiesText":"T01 Gestão de Informações e Acervo · F01 Gestão de Demandas e Fluxo Operacional · T07 Interface e Passagem de Bastão"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você sabe quais campos são obrigatórios em demandas, cards e lançamentos do SISRAMOS e o que cada status significa?","sourceRef":"Autoavaliação!A9:E9"},{"number":2,"dimension":"Execução","question":"Você registra e atualiza cards, responsáveis, prazos e passagens de bastão no SISRAMOS sem precisar de conferência?","sourceRef":"Autoavaliação!A10:E10"},{"number":3,"dimension":"Julgamento e decisão","question":"Ao encontrar um registro inconsistente (sem dono, sem prazo, parado), você sabe se deve corrigir, reclassificar ou acionar alguém — e sabe ler o que um painel do Radar Vital está pedindo?","sourceRef":"Autoavaliação!A11:E11"},{"number":4,"dimension":"Qualidade e consistência","question":"As informações que você registra são confiáveis a ponto de a gestão decidir com base nelas sem conferir por fora?","sourceRef":"Autoavaliação!A12:E12"}],"sourceRefs":["Catálogo de Capacidades!A6:D6","Fichas de Capacidade!A6:P6"]}$$::jsonb, $$[{"id":"T02-AS-01","level":1,"text":"Registros completos e compreensíveis","kind":"evidence","guidance":"Amostra de registros feitos pela pessoa, campo a campo.","reviewCheck":"Cliente, setor, responsável, prazo e descrição corretos; outra pessoa entende o card.","supportingEvidence":"Cards sorteados pelo avaliador.","insufficientEvidence":"Registros escolhidos pela própria pessoa.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Tamanho da amostra: A definir (a ficha v1.0 previa 20 registros).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-AS-02","level":1,"text":"Status fiel à realidade","kind":"evidence","guidance":"Comparação do status de cards com a situação real confirmada com o responsável.","reviewCheck":"Nada concluído como aberto, nem parado como em andamento.","supportingEvidence":"Histórico de status; confirmação do responsável.","insufficientEvidence":"Status atualizado em lote às vésperas da avaliação.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-AS-03","level":1,"text":"Extrai e lê informação do sistema corretamente","kind":"evidence","guidance":"Uso dos painéis para alimentar relatórios ou respostas.","reviewCheck":"Dados extraídos batem com o sistema; leitura correta do que o painel mostra.","supportingEvidence":"Relatório produzido; painel correspondente.","insufficientEvidence":"Copiar números sem entender o que representam.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-AU-01","level":2,"text":"Audita e trata inconsistências","kind":"evidence","guidance":"Registro de auditoria e amostra dos itens apontados.","reviewCheck":"Inconsistências eram reais; corrigidas na alçada ou encaminhadas ao responsável.","supportingEvidence":"Lista de auditoria; histórico dos cards.","insufficientEvidence":"Lista de problemas sem providência.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"Confira se os itens corrigidos não voltaram a aparecer.","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-AU-02","level":2,"text":"Interpreta painéis para decidir","kind":"evidence","guidance":"Leitura de um painel real apresentado pelo avaliador.","reviewCheck":"Explica o que o painel mostra e qual ação aquilo pede.","supportingEvidence":"Painel real; ação tomada no período.","insufficientEvidence":"Descrever o painel sem tirar conclusão.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"O que este painel indica e o que você faria hoje?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-AU-03","level":2,"text":"Registros da área confiáveis sem conferência","kind":"evidence","guidance":"Consulta aos gestores que usam os dados da pessoa.","reviewCheck":"Gestão decide com base nos registros sem controle paralelo.","supportingEvidence":"Relato dos gestores; amostra de registros.","insufficientEvidence":"Ausência de reclamações sem verificação de amostra.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-MU-01","level":3,"text":"Investiga a causa de inconsistências recorrentes","kind":"evidence","guidance":"Análise de padrões de erro na auditoria geral.","reviewCheck":"Diferencia falta de regra, falha de processo e desconhecimento; propõe tratamento na origem.","supportingEvidence":"Relatório de auditoria geral.","insufficientEvidence":"Correção em massa de sintomas.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-MU-02","level":3,"text":"Define regras de uso que passam a valer","kind":"evidence","guidance":"Regra ou melhoria proposta, aprovada e em vigor.","reviewCheck":"Regra clara, comunicada e aplicada pelos setores.","supportingEvidence":"Regra publicada; registros posteriores.","insufficientEvidence":"Regra escrita mas não adotada.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-MU-03","level":3,"text":"Forma usuários com efeito verificável","kind":"evidence","guidance":"Registros dos treinados depois do treinamento.","reviewCheck":"Menos erros nos registros dos usuários treinados.","supportingEvidence":"Registro de treinamento; amostra antes/depois.","insufficientEvidence":"Lista de presença.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T02-MU-04","level":3,"text":"Apoia a gestão com leitura do Radar Vital","kind":"evidence","guidance":"Leituras apresentadas à gestão.","reviewCheck":"Gestão usou a leitura para decidir.","supportingEvidence":"Ata/registro de reunião de gestão.","insufficientEvidence":"Apresentação sem decisão associada.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T03', $${"code":"T03","nature":"Transversal","title":"Planejamento e Organização do Trabalho","summary":"Decompor uma entrega em etapas, estimar esforço, montar agenda e programação, equilibrar a capacidade da equipe e usar checklists para executar sem esquecimentos.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de decompor uma entrega em etapas, estimar esforço e duração, montar agenda e programação, equilibrar a carga de trabalho com a capacidade disponível e utilizar checklists para executar sem esquecimentos nem retrabalho.","scope":"• decompor entregas em etapas e dependências\r\n• estimar esforço e duração\r\n• montar agenda e programação semanal\r\n• sequenciar por prioridade e dependência\r\n• usar e manter checklists de execução\r\n• replanejar diante de imprevistos e comunicar os afetados\r\n• planejar a capacidade da equipe (quando aplicável)","performanceCriteria":"• Cumprimento do planejado: as entregas acontecem conforme a programação, e quando algo vai atrasar a pessoa avisa antes do prazo, não depois. Como se comprova: comparação entre a agenda planejada e o que foi realmente entregue no período.\r\n• Nenhuma etapa esquecida: a entrega chega completa porque as etapas foram listadas e controladas por checklist. Como se comprova: verificação, em entregas recentes, de devoluções ou retrabalhos causados por etapa esquecida.\r\n• Agenda realista: a carga planejada cabe no tempo disponível; não há sobrecarga permanente nem estimativas sistematicamente otimistas. Como se comprova: análise das estimativas de esforço comparadas com o tempo real gasto.\r\n• Replanejamento comunicado: quando a programação muda, todos os afetados (equipe, outros setores, cliente) ficam sabendo. Como se comprova: consulta aos afetados e verificação dos registros de comunicação.","assisted":"Consegue: organizar o próprio trabalho com agenda e checklist definidos por outra pessoa.\r\nAinda necessita: definição de prioridades e acompanhamento semanal.","autonomous":"Faz sozinho: planeja e reprograma suas entregas e pequenos conjuntos de atividades.\r\nDecide: sequência, prazos internos e quando pedir apoio.","multiplier":"Planeja a programação e a capacidade de uma equipe, equilibra cargas, ensina a planejar e melhora os modelos de planejamento.","certificationEvidence":"ASSISTIDO\r\nO que entregar: sua agenda e seus checklists de 4 semanas seguidas.\r\nComo é avaliado: o acompanhante confere semanalmente o que foi planejado e o que foi cumprido.\r\nAprovado quando: os checklists foram usados de forma consistente e as pendências foram identificadas a tempo.\r\n\r\nAUTÔNOMO\r\nO que entregar: o seu planejamento próprio de 2 meses, com o registro do que foi cumprido e dos desvios sinalizados.\r\nComo é avaliado: cálculo da aderência (entregas no prazo ÷ entregas planejadas) e verificação de que os atrasos foram avisados antes do vencimento.\r\nAprovado quando: a aderência é de pelo menos 80% e todos os desvios foram sinalizados com antecedência.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) a programação de uma equipe conduzida por você durante 1 mês; (2) registro de orientação dada a colegas sobre planejamento.\r\nComo é avaliado: a direção compara carga, prazos e cumprimento da equipe no período e conversa com os orientados.\r\nAprovado quando: a equipe cumpriu a programação sem sobrecarga crônica e os orientados passaram a planejar sozinhos.","prerequisites":"Assistido: nenhum.\r\nAutônomo: nenhum.\r\nMultiplicador: T04 Gestão de Prazos e Prioridades — Autônomo.","limits":"Não abrange definir prioridades estratégicas da empresa nem alocar pessoas fora da sua alçada.","relatedCapabilitiesText":"T04 Gestão de Prazos e Prioridades · F09 Planejamento Técnico · F10 Planejamento e Execução de Campo"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você consegue olhar uma entrega e enxergar suas etapas, dependências e o esforço necessário?","sourceRef":"Autoavaliação!A13:E13"},{"number":2,"dimension":"Execução","question":"Você monta e segue sua própria agenda e checklist semanal?","sourceRef":"Autoavaliação!A14:E14"},{"number":3,"dimension":"Julgamento e decisão","question":"Quando surge um imprevisto, você consegue replanejar, decidir o que fica para depois e avisar quem é afetado?","sourceRef":"Autoavaliação!A15:E15"},{"number":4,"dimension":"Qualidade e consistência","question":"O que você planeja é cumprido — ou os desvios são avisados antes do prazo —, sem etapas esquecidas?","sourceRef":"Autoavaliação!A16:E16"}],"sourceRefs":["Catálogo de Capacidades!A7:D7","Fichas de Capacidade!A7:P7"]}$$::jsonb, $$[{"id":"T03-AS-01","level":1,"text":"Usa checklist e agenda de forma consistente","kind":"evidence","guidance":"Agenda e checklists de um período contínuo.","reviewCheck":"Uso regular, não pontual; etapas marcadas no momento da execução.","supportingEvidence":"Agenda; checklists.","insufficientEvidence":"Checklist preenchido de uma vez ao final.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Período observado: A definir (a ficha v1.0 previa 4 semanas).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-AS-02","level":1,"text":"Sinaliza desvios a tempo","kind":"evidence","guidance":"Atrasos do período e quando foram avisados.","reviewCheck":"Aviso antes do vencimento.","supportingEvidence":"Mensagens ao coordenador; histórico de prazos.","insufficientEvidence":"Justificar atraso depois do prazo.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-AS-03","level":1,"text":"Entrega sem etapa esquecida","kind":"evidence","guidance":"Devoluções ou retrabalho por esquecimento.","reviewCheck":"Entregas completas.","supportingEvidence":"Histórico de devoluções no SISRAMOS.","insufficientEvidence":"Ausência de devoluções em período com poucas entregas.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-AU-01","level":2,"text":"Aderência ao planejado","kind":"evidence","guidance":"Comparação entre planejamento e entregas do período.","reviewCheck":"Maioria das entregas no prazo; desvios explicados.","supportingEvidence":"Planejamento; histórico de entregas.","insufficientEvidence":"Período curto ou atípico.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Percentual mínimo de aderência: A definir (a ficha v1.0 previa 80%).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-AU-02","level":2,"text":"Estimativas realistas","kind":"evidence","guidance":"Esforço estimado × tempo real.","reviewCheck":"Sem otimismo sistemático nem sobrecarga crônica.","supportingEvidence":"Planejamento e registros de tempo.","insufficientEvidence":"Cumprir à custa de horas extras permanentes.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-AU-03","level":2,"text":"Replaneja e comunica","kind":"evidence","guidance":"Mudanças de programação e comunicação aos afetados.","reviewCheck":"Afetados avisados antes; nova sequência coerente.","supportingEvidence":"E-mails/mensagens; consulta aos afetados.","insufficientEvidence":"Comunicar apenas ao gestor e esquecer os demais afetados.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-MU-01","level":3,"text":"Programação de equipe equilibrada","kind":"evidence","guidance":"Programação conduzida e seus resultados.","reviewCheck":"Prazos cumpridos sem sobrecarga crônica de pessoas específicas.","supportingEvidence":"Programação; histórico de entregas e carga.","insufficientEvidence":"Equipe pequena demais para exigir equilíbrio real.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-MU-02","level":3,"text":"Forma outros a planejar","kind":"evidence","guidance":"Colegas orientados.","reviewCheck":"Orientados planejando sozinhos.","supportingEvidence":"Registro de orientação; planejamento dos orientados.","insufficientEvidence":"Orientação pontual sem acompanhamento.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T03-MU-03","level":3,"text":"Melhora modelos de planejamento","kind":"evidence","guidance":"Modelo ou checklist revisado.","reviewCheck":"Em uso pela equipe e com ganho percebido.","supportingEvidence":"Modelo vigente; relato da equipe.","insufficientEvidence":"Modelo criado e não adotado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T04', $${"code":"T04","nature":"Transversal","title":"Gestão de Prazos e Prioridades","summary":"Identificar prazos internos, do cliente e legais, priorizar por risco e impacto, acionar lembretes e avisos e agir antes do vencimento.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de identificar prazos internos, do cliente e legais, priorizar o trabalho por risco e impacto, acionar lembretes e avisos no tempo certo e agir antes do vencimento, de modo que nenhuma obrigação se perca por falta de controle.","scope":"• identificar prazos em licenças, notificações, contratos e demandas\r\n• distinguir prazo legal, contratual e interno\r\n• contar prazos (dias úteis/corridos, a partir de publicação ou ciência)\r\n• registrar prazos em controle e no SISRAMOS\r\n• priorizar por risco e impacto\r\n• emitir lembretes e avisos ao cliente (taxas, vencimentos, renovações)\r\n• escalar riscos de vencimento\r\n• solicitar dilação ou prorrogação quando aplicável","performanceCriteria":"• Nenhum prazo perdido: todo prazo sob sua responsabilidade teve uma ação (cumprimento, pedido de dilação ou escalonamento) antes do vencimento. Como se comprova: cruzamento do controle de prazos com as datas reais de protocolo e entrega.\r\n• Aviso antecipado ao cliente: o cliente é alertado sobre taxas, vencimentos e renovações com tempo suficiente para agir. Como se comprova: verificação das datas dos avisos enviados em relação às datas de vencimento.\r\n• Escalonamento a tempo: quando existe risco de atraso, a pessoa comunica o gestor antes de o problema acontecer, e não depois. Como se comprova: análise de situações de risco do período e de quando foram comunicadas.\r\n• Priorização justificável: a pessoa consegue explicar por que fez uma coisa antes da outra, com base em risco e impacto. Como se comprova: o avaliador apresenta uma lista real de pendências e pede a ordem de prioridade com justificativa.","assisted":"Consegue: registrar e acompanhar prazos já identificados.\r\nAinda necessita: validação da contagem e da priorização.","autonomous":"Faz sozinho: identifica, conta, controla e prioriza prazos e aciona avisos.\r\nDecide: ordem de prioridade, quando alertar o cliente e quando escalar.","multiplier":"Desenha o sistema de controle de prazos, audita carteiras, ensina contagem e priorização e conduz situações críticas (vencimento iminente, prazos conflitantes).","certificationEvidence":"ASSISTIDO\r\nO que entregar: o controle de prazos de 1 carteira de clientes mantido por você.\r\nComo é avaliado: o avaliador confere a contagem de cada prazo (data de início, dias úteis ou corridos, data final).\r\nAprovado quando: não há erro de contagem e todos os prazos da carteira estão registrados.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) o histórico de 3 meses do seu controle de prazos; (2) a resolução escrita de um estudo de caso de contagem de prazo legal.\r\nComo é avaliado: cruzamento do controle com as datas reais de cumprimento e correção do estudo de caso.\r\nAprovado quando: nenhum prazo venceu sem ação nos 3 meses e o estudo de caso foi resolvido corretamente.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) relatório de auditoria das carteiras de outros; (2) registro de treinamento sobre contagem e priorização; (3) relato documentado de uma situação crítica tratada por você.\r\nComo é avaliado: a direção analisa o material e a resolução da situação crítica.\r\nAprovado quando: a auditoria encontrou falhas reais, o treinamento foi aplicado e a situação crítica foi resolvida sem perda de prazo.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T02 Uso e Integridade do SISRAMOS — Assistido.\r\nMultiplicador: Autônomo nesta capacidade há 6 meses.","limits":"Não autoriza assumir compromisso de prazo com órgão ou cliente fora da alçada. Não substitui análise jurídica de prazos processuais.","relatedCapabilitiesText":"F04 Gestão de Obrigações e Condicionantes · T03 Planejamento e Organização do Trabalho · F02 Gestão de Processos Regulatórios"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você distingue prazo legal, contratual e interno e sabe contar prazos (dias úteis/corridos, a partir da publicação ou da ciência)?","sourceRef":"Autoavaliação!A17:E17"},{"number":2,"dimension":"Execução","question":"Você identifica e registra os prazos e envia lembretes e avisos ao cliente com antecedência?","sourceRef":"Autoavaliação!A18:E18"},{"number":3,"dimension":"Julgamento e decisão","question":"Com vários prazos ao mesmo tempo, você consegue priorizar por risco e impacto e decidir quando escalar ou pedir dilação?","sourceRef":"Autoavaliação!A19:E19"},{"number":4,"dimension":"Qualidade e consistência","question":"Os prazos sob sua responsabilidade são cumpridos, sem vencimentos esquecidos e com alertas feitos a tempo?","sourceRef":"Autoavaliação!A20:E20"}],"sourceRefs":["Catálogo de Capacidades!A8:D8","Fichas de Capacidade!A8:P8"]}$$::jsonb, $$[{"id":"T04-AS-01","level":1,"text":"Registra todos os prazos sob seu acompanhamento","kind":"evidence","guidance":"Controle mantido pela pessoa comparado às demandas reais.","reviewCheck":"Prazos lançados com data de início e fim corretas.","supportingEvidence":"Controle; cards do SISRAMOS.","insufficientEvidence":"Controle desatualizado completado para a avaliação.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-AS-02","level":1,"text":"Age antes do vencimento","kind":"evidence","guidance":"Datas dos lembretes em relação aos prazos.","reviewCheck":"Lembretes e cobranças antecedem o vencimento.","supportingEvidence":"E-mails/mensagens; histórico dos cards.","insufficientEvidence":"Lembrete no dia do vencimento como regra.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-AS-03","level":1,"text":"Sinaliza risco ao responsável","kind":"evidence","guidance":"Situações em que um prazo ficou em risco.","reviewCheck":"Responsável informado com tempo de agir.","supportingEvidence":"Comunicação registrada.","insufficientEvidence":"Ausência de riscos sem verificar o período.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-AU-01","level":2,"text":"Nenhum prazo vencido sem ação","kind":"evidence","guidance":"Cruzamento do controle com datas reais de cumprimento.","reviewCheck":"Toda data teve cumprimento, dilação ou escalonamento prévio.","supportingEvidence":"Controle; protocolos; histórico do SISRAMOS.","insufficientEvidence":"Controle limpo sem confronto com datas reais.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Período analisado: A definir (a ficha v1.0 previa 3 meses). Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-AU-02","level":2,"text":"Conta prazos legais corretamente","kind":"evidence","guidance":"Contagem de prazos de licenças, notificações e publicações.","reviewCheck":"Termo inicial, tipo de contagem e data final corretos.","supportingEvidence":"Caso real ou estudo de caso resolvido.","insufficientEvidence":"Usar data informada por outra pessoa.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-AU-03","level":2,"text":"Prioriza com justificativa","kind":"evidence","guidance":"Lista real de pendências apresentada pelo avaliador.","reviewCheck":"Ordem explicada por risco, impacto e consequência.","supportingEvidence":"Raciocínio verbal; histórico de decisões.","insufficientEvidence":"Priorizar pela ordem de chegada.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"Destas pendências, qual você faria primeiro e por quê?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-AU-04","level":2,"text":"Avisa o cliente e escala a tempo","kind":"evidence","guidance":"Avisos ao cliente e escalonamentos internos.","reviewCheck":"Antecedência suficiente para o cliente ou gestor agir.","supportingEvidence":"E-mails de aviso; registros de escalonamento.","insufficientEvidence":"Aviso enviado quando já não havia como agir.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-MU-01","level":3,"text":"Audita controles de outras pessoas","kind":"evidence","guidance":"Auditoria de carteira de terceiros.","reviewCheck":"Falhas reais apontadas e corrigidas.","supportingEvidence":"Relatório de auditoria.","insufficientEvidence":"Auditoria sem achados ou sem providência.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-MU-02","level":3,"text":"Forma pessoas em contagem e priorização","kind":"evidence","guidance":"Evolução dos orientados.","reviewCheck":"Orientados contam e priorizam corretamente sozinhos.","supportingEvidence":"Registro de treinamento; controle dos orientados.","insufficientEvidence":"Treinamento sem verificação.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T04-MU-03","level":3,"text":"Conduz situação crítica sem perda de prazo","kind":"evidence","guidance":"Relato e registros do caso crítico.","reviewCheck":"Diagnóstico rápido, envolvimento certo de setores, prazo preservado.","supportingEvidence":"Cards, protocolos e comunicações do caso.","insufficientEvidence":"Caso resolvido por outra pessoa com participação secundária.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Prazos processuais com efeito jurídico podem exigir análise jurídica; a certificação não a substitui.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T05', $${"code":"T05","nature":"Transversal","title":"Comunicação Profissional","summary":"Redigir e conduzir comunicações claras e objetivas (e-mails, pautas, atas, relatórios de posição, apresentações), adequadas ao público e com registro do que foi combinado.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de redigir e conduzir comunicações claras, objetivas e adequadas ao público — e-mails, pautas, atas, relatórios de posição e apresentações —, registrando o que foi combinado e garantindo que a mensagem gere a ação esperada.","scope":"• redigir e-mails com assunto, contexto, pedido e prazo claros\r\n• preparar pautas e registrar atas com encaminhamentos, responsáveis e prazos\r\n• elaborar relatórios de posição e de produção\r\n• adaptar a linguagem ao público (cliente, órgão, equipe, fornecedor)\r\n• apresentar oralmente com objetividade\r\n• registrar os combinados de forma rastreável\r\n• revisar gramática e aplicar o padrão Ramos","performanceCriteria":"• Clareza: quem recebe a comunicação entende o contexto, o pedido e o prazo sem precisar perguntar de novo. Como se comprova: análise de uma amostra de e-mails e verificação de quantos geraram pedidos de esclarecimento.\r\n• Atas com encaminhamentos: toda reunião conduzida pela pessoa gera ata com o que foi decidido, quem faz o quê e até quando. Como se comprova: conferência das atas das reuniões do período.\r\n• Correção do texto: os textos não têm erros de português ou de informação que prejudiquem a credibilidade da Ramos. Como se comprova: leitura de uma amostra de comunicações externas.\r\n• Tom adequado: a linguagem é ajustada ao público — técnica com órgãos, acessível com o cliente, objetiva com a equipe. Como se comprova: comparação de comunicações destinadas a públicos diferentes.\r\n• Combinados rastreáveis: o que foi acordado fica registrado em local que outra pessoa consegue encontrar. Como se comprova: o avaliador pede o registro de um acordo feito recentemente.","assisted":"Consegue: redigir comunicações rotineiras a partir de modelos.\r\nAinda necessita: revisão antes do envio de comunicações externas.","autonomous":"Faz sozinho: comunica com cliente, equipe e fornecedores, conduz reuniões e registra atas.\r\nDecide: forma, canal e momento da comunicação.","multiplier":"Conduz comunicações sensíveis (conflitos, más notícias, negociações), revisa comunicações de outros, cria modelos e treina a equipe.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 5 comunicações reais (e-mails, atas ou relatórios) escritas por você e revisadas antes do envio.\r\nComo é avaliado: o revisor registra quantas precisaram de correção e de que tipo.\r\nAprovado quando: as 5 foram enviadas sem necessidade de reescrita relevante.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) um portfólio de 10 comunicações reais enviadas sem revisão prévia (e-mails, atas, relatórios de posição); (2) a condução de 2 reuniões, com as atas.\r\nComo é avaliado: o avaliador aplica os critérios de desempenho a cada peça do portfólio e acompanha pelo menos 1 das reuniões.\r\nAprovado quando: o portfólio atende a todos os critérios e as reuniões terminaram com ata e encaminhamentos claros.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) relato documentado de uma comunicação sensível conduzida por você (conflito, má notícia, negociação); (2) modelos de comunicação criados; (3) registro de treinamento.\r\nComo é avaliado: a direção analisa o caso, os modelos e o resultado do treinamento.\r\nAprovado quando: a situação sensível foi resolvida sem desgaste, os modelos estão em uso e os treinados melhoraram suas comunicações.","prerequisites":"Assistido: nenhum.\r\nAutônomo: nenhum.\r\nMultiplicador: Autônomo nesta capacidade há 6 meses.","limits":"Não autoriza falar em nome da Ramos em assuntos comerciais, contratuais ou institucionais fora da alçada. A comunicação formal com órgãos é tratada em F06.","relatedCapabilitiesText":"T06 Relacionamento com Cliente · F06 Comunicação Institucional com Órgãos · T07 Interface e Passagem de Bastão"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você sabe o que uma boa comunicação precisa ter (contexto, pedido, responsável, prazo) e como adaptar a linguagem a cliente, equipe e fornecedor?","sourceRef":"Autoavaliação!A21:E21"},{"number":2,"dimension":"Execução","question":"Você redige e-mails, pautas, atas e relatórios de posição e conduz reuniões?","sourceRef":"Autoavaliação!A22:E22"},{"number":3,"dimension":"Julgamento e decisão","question":"Você sabe escolher canal, tom e momento certos, inclusive em situações delicadas (atraso, reclamação, má notícia)?","sourceRef":"Autoavaliação!A23:E23"},{"number":4,"dimension":"Qualidade e consistência","question":"Suas mensagens são entendidas sem pedido de esclarecimento, sem erros relevantes e com os combinados registrados?","sourceRef":"Autoavaliação!A24:E24"}],"sourceRefs":["Catálogo de Capacidades!A9:D9","Fichas de Capacidade!A9:P9"]}$$::jsonb, $$[{"id":"T05-AS-01","level":1,"text":"Clareza da mensagem","kind":"evidence","guidance":"Amostra de comunicações reais.","reviewCheck":"Contexto, pedido e prazo claros; sem pedido de esclarecimento.","supportingEvidence":"E-mails reais; respostas recebidas.","insufficientEvidence":"Textos preparados só para a avaliação.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Tamanho da amostra: A definir (a ficha v1.0 previa 5 comunicações).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-AS-02","level":1,"text":"Correção e uso do modelo","kind":"evidence","guidance":"Gramática, dados e aplicação do modelo Ramos.","reviewCheck":"Sem erros que prejudiquem a credibilidade.","supportingEvidence":"Comunicações e versão revisada.","insufficientEvidence":"Modelo copiado com informação errada.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-AS-03","level":1,"text":"Registro do contato","kind":"evidence","guidance":"Se o contato fica registrado onde outros encontram.","reviewCheck":"Contato vinculado ao card ou pasta correta.","supportingEvidence":"SISRAMOS; pasta do cliente.","insufficientEvidence":"Comunicação feita apenas por telefone sem registro.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-AU-01","level":2,"text":"Atas com encaminhamentos","kind":"evidence","guidance":"Atas das reuniões conduzidas.","reviewCheck":"Decisões, responsáveis e prazos registrados e acompanhados.","supportingEvidence":"Atas; cards de encaminhamento.","insufficientEvidence":"Ata descritiva sem encaminhamentos.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de comunicações no portfólio: A definir (a ficha v1.0 previa 10 + 2 reuniões).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-AU-02","level":2,"text":"Tom adequado ao público","kind":"evidence","guidance":"Comunicações para cliente, órgão, equipe e terceiros.","reviewCheck":"Linguagem técnica com órgãos, acessível com o cliente, objetiva com a equipe.","supportingEvidence":"Amostra por público.","insufficientEvidence":"Uma única comunicação de cada tipo.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-AU-03","level":2,"text":"Comunicação gera a ação esperada","kind":"evidence","guidance":"Resposta e desdobramento das comunicações.","reviewCheck":"Destinatário age sem pedir esclarecimento.","supportingEvidence":"Respostas recebidas; histórico.","insufficientEvidence":"Envio sem retorno verificado.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-AU-04","level":2,"text":"Combinados rastreáveis","kind":"evidence","guidance":"Pedido de registro de um acordo recente.","reviewCheck":"Registro encontrado rapidamente por outra pessoa.","supportingEvidence":"Ata, e-mail ou card.","insufficientEvidence":"Acordo apenas lembrado de memória.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"Onde está registrado o último combinado com este cliente?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-MU-01","level":3,"text":"Conduz comunicação sensível","kind":"evidence","guidance":"Caso real de conflito, má notícia ou negociação.","reviewCheck":"Relação preservada e assunto resolvido.","supportingEvidence":"Registros do caso; relato dos envolvidos.","insufficientEvidence":"Caso em que outra pessoa conduziu.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-MU-02","level":3,"text":"Revisa e orienta comunicações de outros","kind":"evidence","guidance":"Revisões feitas e orientações dadas.","reviewCheck":"Apontamentos específicos; orientados melhoram.","supportingEvidence":"Versões revisadas; comunicações posteriores.","insufficientEvidence":"Corrigir o texto sem explicar.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T05-MU-03","level":3,"text":"Cria modelos que passam a ser usados","kind":"evidence","guidance":"Modelos de comunicação criados ou melhorados.","reviewCheck":"Em uso pela equipe.","supportingEvidence":"Modelos vigentes; uso observado.","insufficientEvidence":"Modelo guardado e não utilizado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T06', $${"code":"T06","nature":"Transversal","title":"Relacionamento com Cliente","summary":"Conduzir alinhamentos com o cliente, entender a necessidade e o escopo contratado, gerir expectativas, dar retorno sobre o andamento e encaminhar oportunidades ao Comercial.","originLabel":"Transversal (origem: Gestão Interna)","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de conduzir alinhamentos com o cliente, compreender sua necessidade e o escopo contratado, gerir expectativas, dar retorno sobre o andamento e identificar e encaminhar oportunidades ao Comercial, preservando a confiança e a satisfação do cliente.","scope":"• conhecer o escopo contratado de cada cliente\r\n• conduzir alinhamentos e reuniões com o cliente\r\n• traduzir a necessidade do cliente em demanda clara\r\n• identificar o que está fora do escopo\r\n• dar retorno proativo de andamento\r\n• gerir expectativas e tratar reclamações\r\n• encaminhar oportunidades ao Comercial\r\n• registrar os contatos","performanceCriteria":"• Cliente informado sem cobrar: o cliente recebe notícias do andamento antes de precisar pedir. Como se comprova: análise do histórico de contatos — quantos foram iniciados pela Ramos e quantos foram cobranças do cliente.\r\n• Expectativa alinhada: o que o cliente espera (escopo, prazo, resultado) corresponde ao que foi contratado e ao que é realmente possível. Como se comprova: comparação entre o que foi registrado nos alinhamentos e o contrato.\r\n• Escopo protegido: pedidos fora do contrato são identificados e encaminhados ao Comercial, e não executados sem cobertura. Como se comprova: verificação dos pedidos extras do período e do destino que tiveram.\r\n• Reclamações tratadas: toda insatisfação do cliente é registrada, respondida e acompanhada até a solução. Como se comprova: consulta ao registro de reclamações e de seu desfecho.\r\n• Ausência de cobranças repetidas: o mesmo assunto não precisa ser cobrado duas vezes pelo cliente. Como se comprova: busca no histórico de e-mails e contatos por cobranças repetidas sobre o mesmo tema.","assisted":"Consegue: atender contatos rotineiros e registrar solicitações.\r\nAinda necessita: apoio em alinhamentos de escopo e situações de insatisfação.","autonomous":"Faz sozinho: conduz o relacionamento de uma carteira, alinha escopo e expectativas e dá retornos.\r\nDecide: o que está em escopo, o que encaminhar ao Comercial e quando escalar.","multiplier":"Conduz clientes estratégicos e situações críticas, orienta a equipe no atendimento e define o padrão de relacionamento da Ramos.","certificationEvidence":"ASSISTIDO\r\nO que entregar: o registro de 1 mês de atendimentos feitos por você.\r\nComo é avaliado: o avaliador confere se os contatos foram registrados e encaminhados corretamente.\r\nAprovado quando: todos os contatos estão registrados e nenhum ficou sem encaminhamento.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) o histórico de 3 meses de uma carteira de clientes conduzida por você; (2) 2 alinhamentos de escopo realizados com o avaliador presente.\r\nComo é avaliado: análise do histórico em busca de cobranças repetidas e observação direta dos alinhamentos.\r\nAprovado quando: não houve cobranças repetidas no período e os alinhamentos deixaram escopo e expectativas claros para o cliente.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) relato de uma situação crítica com cliente conduzida por você; (2) registro de orientação a atendentes; (3) retorno de clientes da sua carteira.\r\nComo é avaliado: a direção analisa o caso e os retornos e conversa com os orientados.\r\nAprovado quando: a situação crítica foi resolvida mantendo o cliente e o retorno dos clientes é positivo.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T05 Comunicação Profissional — Autônomo.\r\nMultiplicador: T08 Análise e Resolução de Problemas — Autônomo.","limits":"Não autoriza negociar preço, alterar contrato ou prometer serviços fora do escopo (atribuição do Comercial/direção).","relatedCapabilitiesText":"T05 Comunicação Profissional · F01 Gestão de Demandas e Fluxo Operacional · T04 Gestão de Prazos e Prioridades"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você conhece o escopo contratado dos clientes que atende e entende o que eles realmente precisam?","sourceRef":"Autoavaliação!A25:E25"},{"number":2,"dimension":"Execução","question":"Você conduz alinhamentos, dá retorno de andamento e registra os contatos com o cliente?","sourceRef":"Autoavaliação!A26:E26"},{"number":3,"dimension":"Julgamento e decisão","question":"Você identifica quando um pedido está fora de escopo e sabe tratar uma insatisfação, encaminhar ao Comercial ou escalar?","sourceRef":"Autoavaliação!A27:E27"},{"number":4,"dimension":"Qualidade e consistência","question":"Seus clientes ficam informados sem precisar cobrar e com expectativas alinhadas ao que é possível entregar?","sourceRef":"Autoavaliação!A28:E28"}],"sourceRefs":["Catálogo de Capacidades!A10:D10","Fichas de Capacidade!A10:P10"]}$$::jsonb, $$[{"id":"T06-AS-01","level":1,"text":"Registra e encaminha todos os contatos","kind":"evidence","guidance":"Atendimentos do período.","reviewCheck":"Todos registrados; nenhum sem encaminhamento.","supportingEvidence":"SISRAMOS; e-mails.","insufficientEvidence":"Registro só dos contatos formais.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Período observado: A definir (a ficha v1.0 previa 1 mês).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-AS-02","level":1,"text":"Obtém do cliente o que é preciso","kind":"evidence","guidance":"Demandas qualificadas ou levantamentos com informação do cliente.","reviewCheck":"Informações completas na primeira conversa.","supportingEvidence":"Demanda qualificada; pacote de levantamento.","insufficientEvidence":"Várias idas e vindas para a mesma informação.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-AS-03","level":1,"text":"Reconhece o que deve levar adiante","kind":"evidence","guidance":"Casos de escopo, reclamação ou expectativa.","reviewCheck":"Levou ao responsável sem prometer nada.","supportingEvidence":"Mensagens internas.","insufficientEvidence":"Resolver sozinho prometendo ao cliente.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-AU-01","level":2,"text":"Escopo protegido","kind":"evidence","guidance":"Pedidos extras do período e seu destino.","reviewCheck":"Identificados, conversados e encaminhados ao Comercial.","supportingEvidence":"Registros de encaminhamento.","insufficientEvidence":"Pedidos executados sem cobertura.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-AU-02","level":2,"text":"Cliente informado sem cobrar","kind":"evidence","guidance":"Histórico de contatos: iniciados pela Ramos × cobranças.","reviewCheck":"Retorno proativo predominante.","supportingEvidence":"Histórico de e-mails/contatos.","insufficientEvidence":"Retornos só quando cobrado.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Período do histórico: A definir (a ficha v1.0 previa 3 meses).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-AU-03","level":2,"text":"Insatisfações tratadas até o fim","kind":"evidence","guidance":"Reclamações registradas e desfecho.","reviewCheck":"Resposta, acompanhamento e solução.","supportingEvidence":"Registro de reclamações.","insufficientEvidence":"Reclamação respondida sem solução.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-AU-04","level":2,"text":"Alinhamento claro","kind":"evidence","guidance":"Alinhamento observado ou registrado.","reviewCheck":"Cliente sai sabendo escopo, prazo e próximo passo.","supportingEvidence":"Ata/registro do alinhamento.","insufficientEvidence":"Reunião sem registro.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-MU-01","level":3,"text":"Resolve situação crítica mantendo o cliente","kind":"evidence","guidance":"Caso crítico e registros.","reviewCheck":"Cliente mantido; problema resolvido.","supportingEvidence":"Histórico; relato do cliente ou gestor.","insufficientEvidence":"Caso resolvido por outra pessoa.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-MU-02","level":3,"text":"Orienta atendentes com efeito","kind":"evidence","guidance":"Evolução dos orientados.","reviewCheck":"Menos cobranças e reclamações nas carteiras orientadas.","supportingEvidence":"Histórico das carteiras.","insufficientEvidence":"Orientação sem acompanhamento.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T06-MU-03","level":3,"text":"Contribui para o padrão de relacionamento","kind":"evidence","guidance":"Prática proposta e uso.","reviewCheck":"Adotada pela equipe.","supportingEvidence":"Prática registrada.","insufficientEvidence":"Sugestão não implantada.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T07', $${"code":"T07","nature":"Transversal","title":"Interface e Passagem de Bastão","summary":"Definir o que precisa receber para começar e o que precisa entregar ao terminar, acionar e responder outros setores, verificar o aceite e garantir que nenhuma etapa fique sem dono.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de definir o que precisa receber para começar e o que precisa entregar ao terminar, acionar e responder outros setores no formato correto, verificar o aceite da entrega e garantir que nenhuma etapa da cadeia técnica fique sem dono.","scope":"• definir as entradas (insumos mínimos para começar)\r\n• definir as saídas e o critério de aceite\r\n• identificar quem aciona e quem recebe\r\n• solicitar a outro setor com informação completa\r\n• entregar com registro e verificar o aceite\r\n• acompanhar retornos entre setores\r\n• identificar etapas sem responsável\r\n• registrar a passagem de bastão no SISRAMOS","performanceCriteria":"• Entrega aceita de primeira: o que a pessoa entrega a outro setor é aceito sem devolução por falta de informação. Como se comprova: contagem das devoluções registradas no SISRAMOS no período.\r\n• Solicitação completa: quando a pessoa pede algo a outro setor, envia tudo o que ele precisa para começar (objetivo, insumos, prazo, critério de aceite). Como se comprova: análise de uma amostra de solicitações e consulta ao setor que as recebeu.\r\n• Nenhuma etapa sem dono: nas cadeias que a pessoa acompanha, não existe trabalho parado entre setores sem responsável identificado. Como se comprova: verificação das demandas multissetoriais sob sua condução.\r\n• Passagem registrada: toda passagem de bastão fica registrada no SISRAMOS, com data, entrega e destinatário. Como se comprova: conferência dos registros de passagem das demandas do período.","assisted":"Consegue: passar e receber entregas usando o checklist de interface.\r\nAinda necessita: conferência da completude das passagens.","autonomous":"Faz sozinho: conduz as interfaces da sua área, aciona e responde setores e verifica aceites.\r\nDecide: aceitar ou devolver entrada incompleta e quando escalar um bloqueio.","multiplier":"Desenha interfaces entre setores (entradas, saídas, critérios de aceite), coordena cadeias multissetoriais e resolve conflitos de fronteira entre setores.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 5 passagens de bastão feitas por você com o checklist de interface preenchido.\r\nComo é avaliado: o avaliador confere se cada passagem tinha as informações necessárias e consulta o setor que recebeu.\r\nAprovado quando: as 5 passagens foram aceitas sem devolução por falta de informação.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) 10 passagens reais feitas sem conferência prévia; (2) o acompanhamento de uma demanda que passou por vários setores, do início ao fim.\r\nComo é avaliado: contagem de devoluções nas 10 passagens e análise do histórico da demanda multissetorial.\r\nAprovado quando: no máximo 1 das 10 passagens foi devolvida e a demanda multissetorial não ficou parada sem dono em nenhuma etapa.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) uma interface entre setores desenhada por você (entradas, saídas e critério de aceite) e implantada; (2) relato de um conflito de fronteira entre setores resolvido.\r\nComo é avaliado: a direção verifica se a interface está em uso e conversa com os setores envolvidos.\r\nAprovado quando: a interface reduziu devoluções entre os setores e o conflito foi resolvido com acordo registrado.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T02 Uso e Integridade do SISRAMOS — Assistido.\r\nMultiplicador: F01 Gestão de Demandas e Fluxo Operacional — Autônomo.","limits":"Não autoriza executar o trabalho técnico de outro setor nem redefinir responsabilidades setoriais (atribuição da gestão/PAD).","relatedCapabilitiesText":"F01 Gestão de Demandas e Fluxo Operacional · T02 Uso e Integridade do SISRAMOS · T05 Comunicação Profissional"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você sabe o que precisa receber para começar seu trabalho e o que precisa entregar, a quem e com qual critério de aceite?","sourceRef":"Autoavaliação!A29:E29"},{"number":2,"dimension":"Execução","question":"Você aciona outros setores com informação completa, entrega com registro e verifica se a entrega foi aceita?","sourceRef":"Autoavaliação!A30:E30"},{"number":3,"dimension":"Julgamento e decisão","question":"Ao receber uma entrada incompleta ou perceber uma etapa sem dono, você sabe se deve aceitar, devolver ou escalar?","sourceRef":"Autoavaliação!A31:E31"},{"number":4,"dimension":"Qualidade e consistência","question":"Suas entregas são aceitas sem devolução por falta de informação e nada fica parado entre setores sem dono?","sourceRef":"Autoavaliação!A32:E32"}],"sourceRefs":["Catálogo de Capacidades!A11:D11","Fichas de Capacidade!A11:P11"]}$$::jsonb, $$[{"id":"T07-AS-01","level":1,"text":"Passagem completa","kind":"evidence","guidance":"Amostra de passagens e checklist.","reviewCheck":"Objetivo, insumos, prazo e o que falta informados.","supportingEvidence":"Checklist; cards.","insufficientEvidence":"Passagem completada depois por outra pessoa.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Tamanho da amostra: A definir (a ficha v1.0 previa 5 passagens).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-AS-02","level":1,"text":"Aceita sem devolução","kind":"evidence","guidance":"Devoluções das passagens analisadas.","reviewCheck":"Sem devolução por falta de informação.","supportingEvidence":"Histórico de devoluções no SISRAMOS.","insufficientEvidence":"Aceite informal sem registro.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-AS-03","level":1,"text":"Registrada no sistema","kind":"evidence","guidance":"Registro da passagem.","reviewCheck":"Data, entrega e destinatário registrados.","supportingEvidence":"SISRAMOS.","insufficientEvidence":"Combinado só verbal.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-AU-01","level":2,"text":"Solicita com informação completa","kind":"evidence","guidance":"Amostra de solicitações e consulta ao receptor.","reviewCheck":"Receptor começa sem pedir complemento.","supportingEvidence":"Solicitações; relato do setor receptor.","insufficientEvidence":"Solicitação completada depois.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de passagens: A definir (a ficha v1.0 previa 10).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-AU-02","level":2,"text":"Verifica aceite e trata devoluções","kind":"evidence","guidance":"Aceites e devoluções do período.","reviewCheck":"Cobra aceite; devolve entrada incompleta com motivo claro.","supportingEvidence":"Histórico SISRAMOS.","insufficientEvidence":"Aceitar tudo para evitar atrito.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-AU-03","level":2,"text":"Nenhuma etapa sem dono","kind":"evidence","guidance":"Demanda multissetorial sob sua condução.","reviewCheck":"Sem período parado sem responsável.","supportingEvidence":"Histórico da demanda.","insufficientEvidence":"Demanda que fluiu sem obstáculos (não testa reação).","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-MU-01","level":3,"text":"Desenha interface que passa a ser usada","kind":"evidence","guidance":"Interface documentada e uso pelos setores.","reviewCheck":"Entradas, saídas e aceite claros e adotados.","supportingEvidence":"Documento; passagens posteriores.","insufficientEvidence":"Documento não adotado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-MU-02","level":3,"text":"Reduz devoluções entre setores","kind":"evidence","guidance":"Devoluções antes e depois.","reviewCheck":"Queda observável.","supportingEvidence":"Dados do SISRAMOS.","insufficientEvidence":"Período curto demais para comparar.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T07-MU-03","level":3,"text":"Resolve conflito de fronteira","kind":"evidence","guidance":"Caso real e acordo.","reviewCheck":"Acordo registrado e respeitado.","supportingEvidence":"Ata/registro; relato dos setores.","insufficientEvidence":"Conflito encerrado por decisão da direção sem mediação.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T08', $${"code":"T08","nature":"Transversal","title":"Análise e Resolução de Problemas","summary":"Diagnosticar situações (demandas paradas, retrabalho, exigências, inconsistências), identificar a causa, avaliar alternativas e decidir ou escalar com fundamento.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de diagnosticar situações-problema (demandas paradas, retrabalho, exigências, inconsistências), identificar a causa, avaliar alternativas e decidir ou escalar com fundamento, evitando soluções improvisadas e a repetição do problema.","scope":"• descrever o problema com fatos e dados\r\n• distinguir sintoma de causa\r\n• aplicar ferramentas simples de análise (5 porquês, Ishikawa)\r\n• levantar e comparar alternativas\r\n• avaliar risco e impacto\r\n• decidir dentro da alçada ou escalar com recomendação\r\n• verificar se a solução funcionou","performanceCriteria":"• Descrição com fatos: o problema é apresentado com dados concretos (o que aconteceu, onde, quando, com que frequência), e não com impressões. Como se comprova: leitura dos relatos de problema escritos pela pessoa.\r\n• Causa antes da solução: a pessoa investiga por que o problema aconteceu antes de propor o que fazer, separando sintoma de causa. Como se comprova: o avaliador verifica se a análise chega a uma causa que, se removida, impede o problema.\r\n• Decisão justificada: a solução escolhida vem acompanhada das alternativas consideradas e do motivo da escolha. Como se comprova: o avaliador pede que a pessoa explique por que descartou as outras opções.\r\n• Sem reincidência: os problemas tratados pela pessoa não voltam a acontecer pelo mesmo motivo. Como se comprova: consulta ao histórico dos 3 meses seguintes à solução.\r\n• Escalonamento qualificado: quando o problema está fora da alçada, chega ao gestor com diagnóstico e recomendação, e não apenas como queixa. Como se comprova: análise dos escalonamentos feitos pela pessoa no período.","assisted":"Consegue: descrever o problema e levantar os fatos.\r\nAinda necessita: apoio para identificar a causa e decidir.","autonomous":"Faz sozinho: diagnostica e resolve problemas normais da rotina.\r\nDecide: a solução dentro da alçada ou o escalonamento fundamentado.","multiplier":"Trata problemas complexos e sistêmicos entre setores, facilita análises de causa com a equipe e transforma soluções em padrão.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 2 relatos escritos de problemas reais que você presenciou (o que aconteceu, onde, quando, impacto).\r\nComo é avaliado: o avaliador verifica se os relatos trazem fatos suficientes para que outra pessoa entenda e analise o problema.\r\nAprovado quando: os 2 relatos são claros, factuais e completos.\r\n\r\nAUTÔNOMO\r\nO que entregar: 3 análises de problemas reais resolvidos por você, cada uma com descrição, causa identificada, alternativas, solução adotada e verificação do resultado.\r\nComo é avaliado: o avaliador confere a lógica de cada análise e consulta o histórico para ver se o problema voltou.\r\nAprovado quando: nas 3 análises a causa é plausível e a solução funcionou, sem reincidência no período verificado.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) o registro de uma análise de problema sistêmico (envolvendo mais de um setor) facilitada por você com a equipe; (2) a solução transformada em padrão (POP, checklist ou regra).\r\nComo é avaliado: a direção analisa o registro, conversa com os participantes e verifica se o padrão está em uso.\r\nAprovado quando: o problema sistêmico deixou de ocorrer e o padrão foi adotado pelos setores envolvidos.","prerequisites":"Assistido: nenhum.\r\nAutônomo: nenhum.\r\nMultiplicador: T09 Padronização e Melhoria de Métodos — Autônomo.","limits":"Não autoriza decisões fora da alçada (financeiras, contratuais, de pessoal) nem dispensa validação de responsável técnico habilitado.","relatedCapabilitiesText":"T09 Padronização e Melhoria de Métodos · F01 Gestão de Demandas e Fluxo Operacional · T02 Uso e Integridade do SISRAMOS"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Diante de um problema, você consegue descrevê-lo com fatos e separar o sintoma da causa?","sourceRef":"Autoavaliação!A33:E33"},{"number":2,"dimension":"Execução","question":"Você aplica um método simples (como os 5 porquês) para chegar à causa e levantar alternativas?","sourceRef":"Autoavaliação!A34:E34"},{"number":3,"dimension":"Julgamento e decisão","question":"Você consegue decidir a solução dentro da sua alçada ou escalar com diagnóstico e recomendação?","sourceRef":"Autoavaliação!A35:E35"},{"number":4,"dimension":"Qualidade e consistência","question":"Os problemas que você trata deixam de se repetir?","sourceRef":"Autoavaliação!A36:E36"}],"sourceRefs":["Catálogo de Capacidades!A12:D12","Fichas de Capacidade!A12:P12"]}$$::jsonb, $$[{"id":"T08-AS-01","level":1,"text":"Descreve com fatos","kind":"evidence","guidance":"Relatos de problemas.","reviewCheck":"O que, onde, quando, frequência e impacto presentes.","supportingEvidence":"Relatos; histórico dos cards.","insufficientEvidence":"Relato opinativo.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Quantidade de relatos: A definir (a ficha v1.0 previa 2).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-AS-02","level":1,"text":"Separa fato de suposição","kind":"evidence","guidance":"Conteúdo dos relatos.","reviewCheck":"Hipóteses identificadas como hipóteses.","supportingEvidence":"Relatos.","insufficientEvidence":"Conclusões sem base.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-AS-03","level":1,"text":"Leva o problema organizado","kind":"evidence","guidance":"Como o problema chegou a quem decide.","reviewCheck":"Quem decide não precisou reapurar.","supportingEvidence":"Mensagens; relato do gestor.","insufficientEvidence":"Repassar o problema sem informações.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-AU-01","level":2,"text":"Chega à causa","kind":"evidence","guidance":"Lógica das análises.","reviewCheck":"Causa plausível que, removida, impede o problema.","supportingEvidence":"Análises; histórico.","insufficientEvidence":"Tratar o sintoma.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de análises: A definir (a ficha v1.0 previa 3).","reviewQuestion":"Por que o problema aconteceu, e não só o que aconteceu?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-AU-02","level":2,"text":"Decide com alternativas","kind":"evidence","guidance":"Alternativas consideradas e motivo da escolha.","reviewCheck":"Explica por que descartou as outras.","supportingEvidence":"Análise; conversa.","insufficientEvidence":"Única solução considerada.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-AU-03","level":2,"text":"Sem reincidência","kind":"evidence","guidance":"Histórico posterior à solução.","reviewCheck":"Problema não volta pelo mesmo motivo.","supportingEvidence":"Histórico do SISRAMOS.","insufficientEvidence":"Período de observação muito curto.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-AU-04","level":2,"text":"Escala com recomendação","kind":"evidence","guidance":"Escalonamentos do período.","reviewCheck":"Chegam com diagnóstico e proposta.","supportingEvidence":"E-mails/cards de escalonamento.","insufficientEvidence":"Escalar como queixa.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-MU-01","level":3,"text":"Facilita análise sistêmica com a equipe","kind":"evidence","guidance":"Registro da análise e participação dos setores.","reviewCheck":"Causa construída em conjunto e aceita pelos envolvidos.","supportingEvidence":"Registro; relato dos participantes.","insufficientEvidence":"Análise feita sozinho e imposta.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-MU-02","level":3,"text":"Transforma solução em padrão","kind":"evidence","guidance":"Padrão resultante.","reviewCheck":"POP/checklist/regra em uso pelos setores.","supportingEvidence":"Padrão vigente.","insufficientEvidence":"Padrão escrito e não adotado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T08-MU-03","level":3,"text":"Problema deixa de ocorrer","kind":"evidence","guidance":"Dados posteriores.","reviewCheck":"Redução observável da fricção.","supportingEvidence":"Dados do SISRAMOS.","insufficientEvidence":"Período curto.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T09', $${"code":"T09","nature":"Transversal","title":"Padronização e Melhoria de Métodos","summary":"Aplicar e manter o padrão Ramos (modelos, templates, checklists, POPs), identificar recorrências, propor melhorias e encaminhá-las ao PAD com justificativa.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de aplicar e manter o padrão Ramos (modelos, templates, checklists e POPs), identificar recorrências e oportunidades de melhoria, documentar novos métodos e encaminhá-los ao PAD com justificativa e indicação dos setores afetados.","scope":"• conhecer e aplicar modelos, templates, checklists e POPs vigentes\r\n• formatar e padronizar documentos técnicos\r\n• identificar desvios e recorrências\r\n• registrar oportunidades de melhoria com justificativa de recorrência\r\n• redigir e atualizar POPs, modelos e checklists (internos e para o cliente)\r\n• encaminhar melhorias ao PAD e acompanhar a implantação\r\n• manter a biblioteca técnica de referência","performanceCriteria":"• Aderência ao padrão: as entregas da pessoa usam os modelos, templates, checklists e POPs vigentes, sem versões antigas ou formatos improvisados. Como se comprova: conferência de entregas recentes com o checklist de padrão Ramos.\r\n• Melhoria com fundamento: as propostas de melhoria vêm acompanhadas de evidência de que o problema se repete (quantas vezes, em quais demandas, quais setores afetados). Como se comprova: leitura dos registros de melhoria enviados ao PAD.\r\n• Método utilizável por outros: os POPs, modelos e checklists escritos pela pessoa podem ser seguidos por um colega sem explicação adicional. Como se comprova: um colega aplica o documento e relata se conseguiu executar sozinho.\r\n• Padrão comunicado e adotado: quando um padrão muda, a equipe fica sabendo e passa a usar a nova versão. Como se comprova: verificação de entregas posteriores à mudança.","assisted":"Consegue: aplicar o padrão vigente.\r\nAinda necessita: conferência da aderência.","autonomous":"Faz sozinho: aplica e mantém padrões, registra melhorias e atualiza modelos.\r\nDecide: ajustes de forma em modelos e quando encaminhar uma melhoria ao PAD.","multiplier":"Cria e governa métodos e a biblioteca técnica, aprova modelos, treina a equipe e mede a adoção do padrão.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 3 entregas recentes feitas por você.\r\nComo é avaliado: conferência de cada entrega com o checklist de padrão Ramos.\r\nAprovado quando: as 3 seguem o padrão vigente, sem desvios relevantes.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) 2 registros de melhoria enviados ao PAD, com justificativa de recorrência e setores afetados; (2) 1 modelo, checklist ou POP atualizado por você.\r\nComo é avaliado: o avaliador analisa a fundamentação das melhorias e pede a um colega que use o documento atualizado.\r\nAprovado quando: as melhorias têm evidência real de recorrência e o colega consegue usar o documento sem ajuda.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) um método, conjunto de modelos ou parte da biblioteca técnica implantados por você; (2) registro de treinamento da equipe no novo padrão.\r\nComo é avaliado: a direção verifica, após 1 mês, se as entregas da equipe estão usando o novo padrão.\r\nAprovado quando: o padrão foi adotado pela equipe e reduziu desvios ou retrabalho.","prerequisites":"Assistido: nenhum.\r\nAutônomo: nenhum.\r\nMultiplicador: T08 Análise e Resolução de Problemas — Autônomo.","limits":"Não autoriza alterar padrão vigente sem aprovação. Mudanças estruturais de fluxo passam pelo PAD/Plano Mestre.","relatedCapabilitiesText":"T08 Análise e Resolução de Problemas · F08 Revisão e Qualidade Técnica · F07 Produção Técnica Ambiental"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você conhece os modelos, templates, checklists e POPs vigentes da Ramos para o seu trabalho?","sourceRef":"Autoavaliação!A37:E37"},{"number":2,"dimension":"Execução","question":"Você aplica o padrão e mantém modelos e documentos de método atualizados?","sourceRef":"Autoavaliação!A38:E38"},{"number":3,"dimension":"Julgamento e decisão","question":"Você identifica quando um desvio é recorrente e decide se é caso de ajuste simples ou de encaminhamento ao PAD?","sourceRef":"Autoavaliação!A39:E39"},{"number":4,"dimension":"Qualidade e consistência","question":"Suas entregas seguem o padrão e as melhorias que você propõe são claras e adotadas pelos outros?","sourceRef":"Autoavaliação!A40:E40"}],"sourceRefs":["Catálogo de Capacidades!A13:D13","Fichas de Capacidade!A13:P13"]}$$::jsonb, $$[{"id":"T09-AS-01","level":1,"text":"Entregas no padrão vigente","kind":"evidence","guidance":"Conferência de entregas com checklist de padrão.","reviewCheck":"Modelos e formatação corretos, versão vigente.","supportingEvidence":"Entregas recentes.","insufficientEvidence":"Entregas escolhidas a dedo.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Quantidade de entregas: A definir (a ficha v1.0 previa 3).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-AS-02","level":1,"text":"Registra lacunas percebidas","kind":"evidence","guidance":"Registros de lacunas/recorrências.","reviewCheck":"Lacuna descrita com o caso concreto.","supportingEvidence":"Registro no SISRAMOS/PAD.","insufficientEvidence":"Comentário informal sem registro.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-AS-03","level":1,"text":"Usa a versão vigente","kind":"evidence","guidance":"Origem dos modelos usados.","reviewCheck":"Sem versões antigas ou improvisadas.","supportingEvidence":"Arquivos-fonte.","insufficientEvidence":"Modelo copiado de entrega antiga.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-AU-01","level":2,"text":"Melhoria com evidência de recorrência","kind":"evidence","guidance":"Registros de melhoria.","reviewCheck":"Recorrência demonstrada com casos; setores afetados indicados.","supportingEvidence":"Registros no PAD.","insufficientEvidence":"Sugestão genérica.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de registros: A definir (a ficha v1.0 previa 2 melhorias + 1 documento).","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-AU-02","level":2,"text":"Documento de método utilizável","kind":"evidence","guidance":"Colega aplica o documento atualizado.","reviewCheck":"Executa sem explicação adicional.","supportingEvidence":"Documento; relato do colega.","insufficientEvidence":"Avaliação apenas da forma.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-AU-03","level":2,"text":"Confere aderência ao padrão","kind":"evidence","guidance":"Revisões ou conferências feitas pela pessoa.","reviewCheck":"Desvios de padrão identificados e corrigidos.","supportingEvidence":"Apontamentos de revisão.","insufficientEvidence":"Conferir apenas formatação superficial.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-MU-01","level":3,"text":"Método implantado e adotado","kind":"evidence","guidance":"Entregas da equipe após implantação.","reviewCheck":"Uso consistente do novo padrão.","supportingEvidence":"Entregas posteriores; biblioteca.","insufficientEvidence":"Lançamento sem verificação de uso.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-MU-02","level":3,"text":"Treina a equipe no padrão","kind":"evidence","guidance":"Registro de treinamento e aplicação.","reviewCheck":"Equipe aplica sem depender do autor.","supportingEvidence":"Registro; entregas dos treinados.","insufficientEvidence":"Lista de presença.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T09-MU-03","level":3,"text":"Gera ganho mensurável","kind":"evidence","guidance":"Desvios/retrabalho antes e depois.","reviewCheck":"Redução observável.","supportingEvidence":"Apontamentos de revisão; devoluções.","insufficientEvidence":"Percepção subjetiva.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('T10', $${"code":"T10","nature":"Transversal","title":"Formação e Supervisão de Pessoas","summary":"Distribuir e supervisionar trabalho, orientar quem está aprendendo, preparar materiais de treinamento, validar a aprendizagem e formar backups.","originLabel":"Transversal","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de distribuir e supervisionar trabalho, orientar quem está aprendendo, preparar materiais de treinamento, validar a aprendizagem e formar backups, elevando o nível de domínio da equipe nas capacidades da Ramos.","scope":"• distribuir tarefas conforme o nível de domínio de cada pessoa\r\n• acompanhar e dar feedback\r\n• planejar treinamentos\r\n• preparar materiais de treinamento\r\n• acompanhar profissional em formação\r\n• avaliar evidências e validar níveis\r\n• formar backups para responsabilidades críticas\r\n• mapear quem sabe fazer, quem é especialista e quem está aprendendo","performanceCriteria":"• Evolução de quem é formado: as pessoas sob sua orientação sobem de nível nas capacidades em prazo razoável. Como se comprova: comparação do nível dos orientados no início e ao final do período de formação.\r\n• Feedback específico e frequente: o orientado recebe retorno regular sobre o que fez bem e o que precisa melhorar, com exemplos concretos. Como se comprova: consulta aos orientados e leitura dos registros de acompanhamento.\r\n• Backups formados: as responsabilidades críticas da área têm pelo menos uma segunda pessoa apta a assumir. Como se comprova: verificação, no Perfil por Responsabilidade, de quantas responsabilidades da área têm backup.\r\n• Avaliação justa: as decisões sobre nível de domínio se baseiam nas evidências definidas na ficha, e não em simpatia ou tempo de casa. Como se comprova: revisão por outro Multiplicador de uma avaliação feita pela pessoa.","assisted":"Consegue: apoiar a orientação de um colega em tarefas específicas.\r\nAinda necessita: supervisão de quem conduz a formação.","autonomous":"Faz sozinho: supervisiona e orienta pessoas e aplica treinamentos prontos.\r\nDecide: distribuição de tarefas e conteúdo do feedback.","multiplier":"Planeja trilhas de formação, cria materiais, certifica níveis em outras pessoas e forma formadores.","certificationEvidence":"ASSISTIDO\r\nO que entregar: o registro da sua participação em 1 processo de formação conduzido por outra pessoa (o que você orientou, quando, com que resultado).\r\nComo é avaliado: o responsável pela formação confirma sua contribuição.\r\nAprovado quando: sua participação foi efetiva e o orientado reconhece a ajuda recebida.\r\n\r\nAUTÔNOMO\r\nO que entregar: o registro de 3 meses de supervisão de 1 pessoa (tarefas distribuídas, feedbacks dados, evolução observada).\r\nComo é avaliado: o avaliador lê os registros e conversa com a pessoa supervisionada.\r\nAprovado quando: houve feedback regular e a pessoa supervisionada mostrou evolução registrada.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) 2 pessoas que evoluíram de nível sob sua formação; (2) material de treinamento criado por você; (3) 1 avaliação de nível conduzida por você.\r\nComo é avaliado: a direção confere a evolução registrada, analisa o material e revisa a avaliação com outro Multiplicador.\r\nAprovado quando: as 2 pessoas foram certificadas no nível seguinte e a avaliação revisada foi considerada correta e baseada em evidências.","prerequisites":"Assistido: nenhum.\r\nAutônomo: Autônomo na capacidade técnica que vai supervisionar.\r\nMultiplicador: Multiplicador na capacidade técnica que vai certificar.","limits":"Só pode certificar outras pessoas em capacidades nas quais é Multiplicador. Não abrange decisões de RH (contratação, desligamento, remuneração).","relatedCapabilitiesText":"T03 Planejamento e Organização do Trabalho · T09 Padronização e Melhoria de Métodos · F08 Revisão e Qualidade Técnica"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você sabe identificar o nível de domínio de cada pessoa e o que ela precisa para evoluir?","sourceRef":"Autoavaliação!A41:E41"},{"number":2,"dimension":"Execução","question":"Você distribui tarefas, acompanha e dá feedback a quem está aprendendo?","sourceRef":"Autoavaliação!A42:E42"},{"number":3,"dimension":"Julgamento e decisão","question":"Você consegue avaliar evidências e decidir, com justiça, se alguém já atingiu um nível?","sourceRef":"Autoavaliação!A43:E43"},{"number":4,"dimension":"Qualidade e consistência","question":"As pessoas que você orienta evoluem de nível e existem backups formados para as responsabilidades críticas?","sourceRef":"Autoavaliação!A44:E44"}],"sourceRefs":["Catálogo de Capacidades!A14:D14","Fichas de Capacidade!A14:P14"]}$$::jsonb, $$[{"id":"T10-AS-01","level":1,"text":"Orienta sem executar pelo outro","kind":"evidence","guidance":"Tarefas do orientado.","reviewCheck":"Orientado executou com sua orientação.","supportingEvidence":"Relato do orientado; cards.","insufficientEvidence":"Tarefa feita pela pessoa.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-AS-02","level":1,"text":"Comunica dificuldades ao supervisor","kind":"evidence","guidance":"Comunicações ao supervisor.","reviewCheck":"Dificuldades relatadas com fatos.","supportingEvidence":"Mensagens.","insufficientEvidence":"Esconder dificuldades do orientado.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-AS-03","level":1,"text":"Retorno útil","kind":"evidence","guidance":"Feedback dado.","reviewCheck":"Específico e acionável.","supportingEvidence":"Relato do orientado.","insufficientEvidence":"Elogio genérico.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-AU-01","level":2,"text":"Distribui conforme o nível","kind":"evidence","guidance":"Distribuição realizada.","reviewCheck":"Tarefas compatíveis com o nível; desafio adequado a quem aprende.","supportingEvidence":"Cards; mapa de capacidades.","insufficientEvidence":"Distribuição por disponibilidade apenas.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-AU-02","level":2,"text":"Feedback específico e frequente","kind":"evidence","guidance":"Registros de feedback.","reviewCheck":"O que foi bem, o que melhorar e como.","supportingEvidence":"Registros; relato dos orientados.","insufficientEvidence":"Feedback só em avaliação formal.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-AU-03","level":2,"text":"Evolução dos supervisionados","kind":"evidence","guidance":"Desempenho dos orientados no período.","reviewCheck":"Menos correções; mais autonomia.","supportingEvidence":"Histórico de entregas.","insufficientEvidence":"Equipe já experiente.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-MU-01","level":3,"text":"Pessoas formadas sobem de nível","kind":"evidence","guidance":"Nível dos orientados no início e no fim.","reviewCheck":"Progressão certificada.","supportingEvidence":"Histórico de certificações.","insufficientEvidence":"Pessoas que já estavam próximas do nível.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-MU-02","level":3,"text":"Validação de aprendizagem com critério","kind":"evidence","guidance":"Avaliações conduzidas.","reviewCheck":"Decisões baseadas em evidências e critérios do nível.","supportingEvidence":"Registros de avaliação.","insufficientEvidence":"Aprovação por proximidade pessoal.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"Confirme que as certificações conduzidas foram só em capacidades em que é Multiplicador.","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"T10-MU-03","level":3,"text":"Forma backups e formadores","kind":"evidence","guidance":"Responsabilidades críticas cobertas; formadores ativos.","reviewCheck":"Existe backup; formado por ele já orienta.","supportingEvidence":"Mapa de capacidades; relato.","insufficientEvidence":"Backup apenas nominal.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Só pode certificar outras pessoas em capacidades nas quais é Multiplicador; não abrange decisões de RH.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F01', $${"code":"F01","nature":"Funcional","title":"Gestão de Demandas e Fluxo Operacional","summary":"Triar a entrada de solicitações, qualificar a demanda, definir setor e responsáveis, acompanhar demandas que atravessam setores, identificar pendências e demandas sem dono e redistribuir quando necessário.","originLabel":"Gestão Interna","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de triar a entrada de solicitações, qualificar a demanda, definir setor e responsáveis, acompanhar demandas que atravessam setores, identificar pendências, gargalos e demandas sem dono e redistribuir quando necessário, garantindo que toda demanda tenha dono, fluxo e prazo.","scope":"• triar a caixa de e-mail e os canais de entrada\r\n• registrar as solicitações recebidas\r\n• qualificar a demanda (o quê, para quem, prazo, escopo)\r\n• definir setor destinatário e responsáveis\r\n• encaminhar formalmente e verificar o aceite\r\n• acompanhar demandas que atravessam vários setores\r\n• identificar demandas paradas, sem dono, sem fluxo ou mal classificadas\r\n• detectar retrabalho, devoluções e cobranças recorrentes do cliente\r\n• redistribuir demandas classificadas incorretamente\r\n• encaminhar lacunas estruturais ao PAD/Plano Mestre","performanceCriteria":"• Toda demanda com dono: cada demanda registrada tem setor, responsável e prazo definidos. Como se comprova: filtro no SISRAMOS de demandas sem responsável ou sem prazo na carteira da pessoa.\r\n• Triagem no tempo: as solicitações recebidas são registradas e classificadas dentro do prazo interno definido. Como se comprova: comparação entre a data de recebimento e a data de registro de uma amostra de demandas.\r\n• Classificação certa: as demandas chegam ao setor correto e raramente precisam ser redistribuídas. Como se comprova: contagem de redistribuições por erro de classificação no período.\r\n• Paradas tratadas: demandas sem movimentação são identificadas e destravadas ou escaladas. Como se comprova: verificação das demandas paradas há mais de 5 dias úteis e do que foi feito com elas.\r\n• Fricções registradas: retrabalhos, devoluções e cobranças repetidas são registrados e encaminhados para melhoria. Como se comprova: leitura dos registros de fricção encaminhados ao PAD.","assisted":"Consegue: triar e registrar demandas com regras definidas.\r\nAinda necessita: validação da classificação e do destino.","autonomous":"Faz sozinho: qualifica, distribui e acompanha demandas e audita pendências.\r\nDecide: setor, responsável e redistribuição.","multiplier":"Coordena o fluxo técnico ponta a ponta, define regras de triagem e distribuição, trata gargalos sistêmicos e forma a equipe de gestão de demandas.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 2 semanas de triagem e classificação de demandas feitas por você.\r\nComo é avaliado: um Autônomo confere cada classificação (setor, responsável, prazo).\r\nAprovado quando: no máximo 10% das demandas precisaram de correção na classificação.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) 1 mês de distribuição de demandas sem conferência prévia; (2) relatório de uma auditoria de pendências feita por você.\r\nComo é avaliado: contagem das redistribuições por erro e conferência dos itens da auditoria.\r\nAprovado quando: a taxa de redistribuição é baixa e as pendências apontadas na auditoria eram reais e foram tratadas.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) 3 meses de coordenação do fluxo técnico; (2) uma regra de distribuição implantada; (3) relatório de gargalos com propostas.\r\nComo é avaliado: a direção compara indicadores do fluxo antes e depois e analisa o relatório.\r\nAprovado quando: o fluxo apresenta menos demandas paradas ou sem dono e a regra está em uso.","prerequisites":"Assistido: T02 Uso e Integridade do SISRAMOS — Assistido.\r\nAutônomo: T07 Interface e Passagem de Bastão — Autônomo.\r\nMultiplicador: T08 Análise e Resolução de Problemas — Autônomo.","limits":"Não executa o trabalho técnico das demandas. Não redefine responsabilidades dos setores (atribuição do PAD/direção).","relatedCapabilitiesText":"T07 Interface e Passagem de Bastão · T02 Uso e Integridade do SISRAMOS · T08 Análise e Resolução de Problemas"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você entende as regras de triagem e sabe qual setor e responsável cuidam de cada tipo de demanda?","sourceRef":"Autoavaliação!A45:E45"},{"number":2,"dimension":"Execução","question":"Você tria, registra, qualifica, encaminha e acompanha demandas até o aceite pelo setor?","sourceRef":"Autoavaliação!A46:E46"},{"number":3,"dimension":"Julgamento e decisão","question":"Diante de uma demanda mal descrita, parada, sem dono ou mal classificada, você sabe redistribuir ou escalar?","sourceRef":"Autoavaliação!A47:E47"},{"number":4,"dimension":"Qualidade e consistência","question":"As demandas que passam por você ficam com setor, responsável e prazo definidos e raramente precisam ser reclassificadas?","sourceRef":"Autoavaliação!A48:E48"}],"sourceRefs":["Catálogo de Capacidades!A15:D15","Fichas de Capacidade!A15:P15"]}$$::jsonb, $$[{"id":"F01-AS-01","level":1,"text":"Nada se perde na entrada","kind":"evidence","guidance":"Comparação da caixa de entrada com os registros.","reviewCheck":"Todas as solicitações registradas no mesmo dia.","supportingEvidence":"Caixa de entrada; SISRAMOS.","insufficientEvidence":"Período de baixo volume.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-AS-02","level":1,"text":"Classificação conforme a regra","kind":"evidence","guidance":"Amostra de classificações.","reviewCheck":"Setor e tipo corretos nos casos usuais.","supportingEvidence":"Cards; regras de triagem.","insufficientEvidence":"Classificações corrigidas depois por outro.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-AS-03","level":1,"text":"Confirma e pede informação faltante","kind":"evidence","guidance":"Respostas a quem solicitou.","reviewCheck":"Confirmação objetiva e pedido do que falta.","supportingEvidence":"E-mails.","insufficientEvidence":"Silêncio até a demanda ser executada.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-AU-01","level":2,"text":"Qualifica demandas vagas","kind":"evidence","guidance":"Demandas recebidas vagas e a qualificação feita.","reviewCheck":"O quê, para quem, prazo e escopo definidos antes de seguir.","supportingEvidence":"Cards (antes/depois); conversa com o cliente.","insufficientEvidence":"Encaminhar demanda vaga para o setor 'descobrir'.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-AU-02","level":2,"text":"Decide destino e responsável com acerto","kind":"evidence","guidance":"Reclassificações posteriores das demandas distribuídas.","reviewCheck":"Poucas devoluções por destino errado.","supportingEvidence":"Histórico SISRAMOS.","insufficientEvidence":"Volume pequeno de distribuições.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-AU-03","level":2,"text":"Audita e trata pendências","kind":"evidence","guidance":"Auditoria de demandas paradas/sem dono.","reviewCheck":"Itens identificados e resolvidos ou encaminhados (inclusive ao PAD).","supportingEvidence":"Registro da auditoria; cards.","insufficientEvidence":"Listar pendências sem agir.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"Mostre uma demanda que estava sem dono e o que aconteceu com ela.","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-MU-01","level":3,"text":"Define regras de fluxo em uso","kind":"evidence","guidance":"Regras de triagem/distribuição.","reviewCheck":"Claras, aplicadas pela equipe e com menos exceções.","supportingEvidence":"Regras; distribuições posteriores.","insufficientEvidence":"Regra conhecida só pelo autor.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-MU-02","level":3,"text":"Coordena cadeia multissetorial","kind":"evidence","guidance":"Demanda que atravessou vários setores.","reviewCheck":"Sem etapa órfã; atrasos antecipados.","supportingEvidence":"Histórico da demanda.","insufficientEvidence":"Cadeia simples.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F01-MU-03","level":3,"text":"Forma a equipe do fluxo","kind":"evidence","guidance":"Evolução dos orientados.","reviewCheck":"Orientados qualificam e distribuem sozinhos.","supportingEvidence":"Registros; cards dos orientados.","insufficientEvidence":"Treinamento sem verificação.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F02', $${"code":"F02","nature":"Funcional","title":"Gestão de Processos Regulatórios","summary":"Compreender uma demanda regulatória, identificar o caminho aplicável (modalidade e órgão), estruturar requisitos, organizar documentação e peças técnicas, conduzir o processo e acompanhar sua evolução perante o órgão competente. Vale para licenças, renovações, outorgas e regularizações complementares (alvará, AVCB, habite-se, VISA, produtos controlados).","originLabel":"Processos e Órgãos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de compreender uma demanda regulatória, identificar o caminho aplicável (modalidade e órgão competente), estruturar requisitos, organizar documentação e peças técnicas, conduzir o processo e acompanhar sua evolução perante o órgão até a decisão final — em licenças, renovações, outorgas e regularizações complementares.","scope":"• interpretar a demanda e a atividade do cliente\r\n• identificar enquadramento, modalidade e órgão competente\r\n• levantar requisitos e documentos exigidos\r\n• identificar estudos, projetos e levantamentos necessários\r\n• prever taxas e publicações do processo\r\n• mapear dependências e definir o caminho regulatório\r\n• estruturar, montar e protocolar o processo\r\n• acompanhar o andamento e tratar exigências\r\n• conduzir renovações de licenças e outorgas\r\n• conduzir regularizações complementares (alvará, AVCB/CLCB, habite-se, VISA, produtos controlados, anuências)","performanceCriteria":"• Enquadramento correto: a modalidade de licença, outorga ou regularização e o órgão competente são definidos corretamente desde o início. Como se comprova: o avaliador revisa o enquadramento de processos conduzidos pela pessoa à luz da legislação.\r\n• Protocolo completo: o processo é protocolado com todos os documentos e peças exigidos, sem gerar exigência por algo que poderia ter sido previsto. Como se comprova: análise das exigências recebidas nos processos da pessoa e da causa de cada uma.\r\n• Acompanhamento periódico: o andamento de cada processo é consultado na frequência definida e registrado no SISRAMOS. Como se comprova: verificação das datas de consulta registradas.\r\n• Renovação no prazo: pedidos de renovação são protocolados dentro do prazo legal (por exemplo, 120 dias antes do vencimento, quando aplicável). Como se comprova: cruzamento das datas de vencimento com as datas de protocolo.\r\n• Cliente informado: o cliente sabe em que fase está o processo e o que falta. Como se comprova: análise dos relatórios e comunicações enviados ao cliente.","assisted":"Consegue: montar e acompanhar processos com roteiro definido.\r\nAinda necessita: validação do enquadramento e conferência antes do protocolo.","autonomous":"Faz sozinho: conduz processos normais de licenciamento, renovação e regularização.\r\nDecide: modalidade, documentos necessários e momento do protocolo.","multiplier":"Planeja caminhos regulatórios complexos (múltiplos órgãos, empreendimentos atípicos), revisa processos de outros, forma a equipe e mantém os roteiros regulatórios.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 3 processos montados por você, antes do protocolo.\r\nComo é avaliado: um Autônomo confere enquadramento, documentos e peças de cada processo antes de ele ser protocolado.\r\nAprovado quando: os 3 processos estão corretos no enquadramento e precisam apenas de ajustes pequenos.\r\n\r\nAUTÔNOMO\r\nO que entregar: 3 processos de tipos diferentes (ex.: licença, renovação e regularização complementar) conduzidos por você do protocolo até a decisão do órgão.\r\nComo é avaliado: análise do histórico de cada processo, das exigências recebidas e de suas causas.\r\nAprovado quando: nenhum dos 3 teve exigência por falha evitável e todos foram acompanhados até a decisão.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) o planejamento regulatório de um caso complexo (múltiplos órgãos ou atividade atípica); (2) revisões de processos feitas por você para colegas; (3) um roteiro regulatório elaborado.\r\nComo é avaliado: a direção analisa o planejamento e o roteiro e confere o resultado dos processos revisados.\r\nAprovado quando: o caminho definido foi aceito pelos órgãos e o roteiro está sendo usado pela equipe.","prerequisites":"Assistido: T04 Gestão de Prazos e Prioridades — Assistido.\r\nAutônomo: F05 Gestão Documental Regulatória — Autônomo e F03 Operação de Sistemas e Plataformas Regulatórias — Assistido.\r\nMultiplicador: T08 Análise e Resolução de Problemas — Autônomo.","limits":"Não abrange elaborar os estudos técnicos (F07) nem assinar como responsável técnico. Não substitui assessoria jurídica em defesas e recursos administrativos.","relatedCapabilitiesText":"F03 Operação de Sistemas e Plataformas · F05 Gestão Documental Regulatória · F06 Comunicação Institucional com Órgãos · F04 Gestão de Obrigações e Condicionantes · E02 Regularização e Gestão Hídrica"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Diante de uma demanda regulatória, você consegue identificar o enquadramento, a modalidade, o órgão competente e os requisitos?","sourceRef":"Autoavaliação!A49:E49"},{"number":2,"dimension":"Execução","question":"Você monta, protocola e acompanha processos de licenciamento, renovação e regularização?","sourceRef":"Autoavaliação!A50:E50"},{"number":3,"dimension":"Julgamento e decisão","question":"Você define o caminho regulatório e suas dependências (estudos, taxas, publicações) e decide quando o processo está pronto para protocolo?","sourceRef":"Autoavaliação!A51:E51"},{"number":4,"dimension":"Qualidade e consistência","question":"Seus processos são protocolados completos, sem exigência por falha evitável, e as renovações saem no prazo?","sourceRef":"Autoavaliação!A52:E52"}],"sourceRefs":["Catálogo de Capacidades!A16:D16","Fichas de Capacidade!A16:P16"]}$$::jsonb, $$[{"id":"F02-AS-01","level":1,"text":"Monta processo completo com roteiro","kind":"evidence","guidance":"Processos montados e conferência pré-protocolo.","reviewCheck":"Documentos completos e na ordem exigida.","supportingEvidence":"Processo; checklist de conferência.","insufficientEvidence":"Processo reorganizado pelo conferente.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-AS-02","level":1,"text":"Acompanha e registra andamento","kind":"evidence","guidance":"Registros de movimentação.","reviewCheck":"Movimentações registradas tempestivamente.","supportingEvidence":"SISRAMOS; consultas ao órgão.","insufficientEvidence":"Acompanhamento só quando cobrado.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-AS-03","level":1,"text":"Entende a origem das obrigações","kind":"evidence","guidance":"Leitura de licença feita pela pessoa.","reviewCheck":"Relaciona condicionantes à licença.","supportingEvidence":"Conversa sobre uma licença real.","insufficientEvidence":"Decorar tipos de licença.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"Esta condicionante decorre de qual parte da licença?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-AU-01","level":2,"text":"Enquadra corretamente","kind":"evidence","guidance":"Modalidade e órgão definidos pela pessoa.","reviewCheck":"Enquadramento coerente com a atividade e a norma.","supportingEvidence":"Processo; justificativa do enquadramento.","insufficientEvidence":"Enquadramento copiado de processo anterior sem análise.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"Por que esta modalidade e não outra?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-AU-02","level":2,"text":"Conduz do protocolo à decisão","kind":"evidence","guidance":"Histórico de processos conduzidos.","reviewCheck":"Sem perda de prazo; acompanhamento ativo.","supportingEvidence":"Protocolos; histórico.","insufficientEvidence":"Atuação apenas em parte do processo.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de processos: A definir. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-AU-03","level":2,"text":"Trata exigências com coerência","kind":"evidence","guidance":"Respostas a notificações/exigências.","reviewCheck":"Resposta atende ao que foi pedido e é coerente com o processo.","supportingEvidence":"Resposta protocolada; retorno do órgão.","insufficientEvidence":"Resposta redigida por outro.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-AU-04","level":2,"text":"Decide renovação e dilação a tempo","kind":"evidence","guidance":"Renovações e dilações conduzidas.","reviewCheck":"Protocoladas no prazo e com fundamento.","supportingEvidence":"Protocolos.","insufficientEvidence":"Renovação feita por lembrete de terceiro.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-MU-01","level":3,"text":"Planeja caminho complexo com acerto","kind":"evidence","guidance":"Plano regulatório e desdobramento.","reviewCheck":"Dependências previstas; sem retrabalho por falha de enquadramento.","supportingEvidence":"Plano; histórico dos processos.","insufficientEvidence":"Caso simples apresentado como complexo.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-MU-02","level":3,"text":"Revisa processos de outros","kind":"evidence","guidance":"Revisões feitas.","reviewCheck":"Apontamentos que evitam exigências.","supportingEvidence":"Registros de revisão.","insufficientEvidence":"Revisão superficial.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F02-MU-03","level":3,"text":"Mantém roteiros e forma a equipe","kind":"evidence","guidance":"Roteiros e evolução dos orientados.","reviewCheck":"Roteiros em uso; orientados conduzindo sozinhos.","supportingEvidence":"Roteiros; certificações dos orientados.","insufficientEvidence":"Roteiro desatualizado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Certificação interna não autoriza assinar como responsável técnico nem substitui assessoria jurídica em defesas e recursos.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F03', $${"code":"F03","nature":"Funcional","title":"Operação de Sistemas e Plataformas Regulatórias","summary":"Operar portais e sistemas de órgãos (IBAMA/CTF, SINIR, CEPROF/SISFLORA, CERH, portais estaduais e municipais), gerir cadastros, acessos, senhas e certificados digitais, protocolar, juntar documentos e emitir guias e taxas.","originLabel":"Processos e Órgãos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de operar portais e sistemas de órgãos (IBAMA/CTF, SINIR, CEPROF/SISFLORA, CERH, portais estaduais e municipais), gerir cadastros, acessos, senhas e certificados digitais, protocolar e juntar documentos e emitir guias, taxas e declarações com precisão.","scope":"• criar e manter cadastros em plataformas de órgãos\r\n• gerir acessos, senhas e certificados digitais (validade e guarda)\r\n• protocolar processos e juntar documentos em portais\r\n• emitir guias e taxas (DAE, DAM, TCFA)\r\n• enviar declarações (RAPP, DMR, MTR/CDF, CERH)\r\n• emitir certidões e comprovantes de regularidade\r\n• emitir e atualizar ART em plataformas de conselho\r\n• arquivar os comprovantes gerados","performanceCriteria":"• Dados corretos: as informações lançadas nas plataformas (cadastros, declarações, guias) estão corretas e coerentes com os documentos do cliente. Como se comprova: conferência de uma amostra de lançamentos com os documentos de origem.\r\n• Acessos válidos: senhas, cadastros e certificados digitais dos clientes estão em dia e controlados, sem vencimento inesperado. Como se comprova: verificação do controle de acessos e certificados da carteira.\r\n• Comprovantes arquivados: todo protocolo, guia e declaração enviados tem comprovante salvo no acervo do cliente. Como se comprova: sorteio de operações e busca pelo comprovante.\r\n• Sem multa por erro operacional: nenhuma multa, pendência ou bloqueio foi causado por erro de operação da pessoa. Como se comprova: consulta às situações cadastrais dos clientes e ao histórico de ocorrências.","assisted":"Consegue: operar plataformas seguindo roteiro passo a passo.\r\nAinda necessita: conferência das operações antes da conclusão.","autonomous":"Faz sozinho: opera as principais plataformas e gere os acessos de uma carteira.\r\nDecide: como resolver erros operacionais comuns.","multiplier":"Domina plataformas novas ou complexas, cria roteiros, treina a equipe e resolve problemas junto aos suportes dos órgãos.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 5 operações em plataformas (protocolo, emissão de guia, declaração ou cadastro) feitas por você.\r\nComo é avaliado: um Autônomo confere cada operação e seu comprovante.\r\nAprovado quando: as 5 operações estão corretas e com comprovante arquivado.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) operações reais em 4 plataformas diferentes (ex.: IBAMA/CTF, SINIR, CERH, portal estadual); (2) o controle de acessos e certificados de uma carteira de clientes.\r\nComo é avaliado: conferência de uma amostra das operações e do controle de acessos.\r\nAprovado quando: não há erro nas operações e nenhum acesso ou certificado da carteira está vencido ou desconhecido.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) roteiros passo a passo de plataformas criados por você; (2) registro de treinamento.\r\nComo é avaliado: um colega executa uma operação seguindo apenas o roteiro.\r\nAprovado quando: o colega conclui a operação corretamente sem ajuda.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T01 Gestão de Informações e Acervo — Autônomo.\r\nMultiplicador: Autônomo nesta capacidade há 6 meses.","limits":"Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada. Não decide o conteúdo técnico declarado.","relatedCapabilitiesText":"F02 Gestão de Processos Regulatórios · F04 Gestão de Obrigações e Condicionantes · F05 Gestão Documental Regulatória"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você conhece as plataformas dos órgãos (IBAMA/CTF, SINIR, CEPROF/SISFLORA, CERH, portais estaduais e municipais) e o que cada uma exige?","sourceRef":"Autoavaliação!A53:E53"},{"number":2,"dimension":"Execução","question":"Você protocola, emite guias e taxas, envia declarações e gerencia cadastros, acessos e certificados digitais?","sourceRef":"Autoavaliação!A54:E54"},{"number":3,"dimension":"Julgamento e decisão","question":"Quando a plataforma dá erro ou o caso foge do roteiro, você consegue resolver ou acionar o suporte do órgão?","sourceRef":"Autoavaliação!A55:E55"},{"number":4,"dimension":"Qualidade e consistência","question":"Suas operações saem com dados corretos, comprovantes arquivados e sem multa ou pendência por erro operacional?","sourceRef":"Autoavaliação!A56:E56"}],"sourceRefs":["Catálogo de Capacidades!A17:D17","Fichas de Capacidade!A17:P17"]}$$::jsonb, $$[{"id":"F03-AS-01","level":1,"text":"Executa operações com roteiro","kind":"evidence","guidance":"Operações realizadas e conferência.","reviewCheck":"Concluídas corretamente com poucos ajustes.","supportingEvidence":"Comprovantes; registro da conferência.","insufficientEvidence":"Operação refeita pelo conferente.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-AS-02","level":1,"text":"Arquiva comprovantes","kind":"evidence","guidance":"Comprovantes das operações.","reviewCheck":"Arquivados no padrão no mesmo dia.","supportingEvidence":"Pastas; cards.","insufficientEvidence":"Comprovante só no e-mail.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-AS-03","level":1,"text":"Usa credenciais com segurança","kind":"evidence","guidance":"Uso de senhas e certificados.","reviewCheck":"Somente para a finalidade autorizada; sem exposição.","supportingEvidence":"Controle de acessos.","insufficientEvidence":"Compartilhar senha por mensagem aberta.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-AU-01","level":2,"text":"Opera sem erro que prejudique o processo","kind":"evidence","guidance":"Operações do período.","reviewCheck":"Sem protocolos inválidos ou atrasos por erro operacional.","supportingEvidence":"Comprovantes; histórico.","insufficientEvidence":"Período com poucas operações.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-AU-02","level":2,"text":"Gere acessos e certificados da carteira","kind":"evidence","guidance":"Controle de acessos.","reviewCheck":"Validades controladas; nenhum vencimento inesperado.","supportingEvidence":"Controle; cadastros.","insufficientEvidence":"Controle sem datas de validade.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-AU-03","level":2,"text":"Resolve erros operacionais comuns","kind":"evidence","guidance":"Casos de erro.","reviewCheck":"Resolvidos sem apoio.","supportingEvidence":"Relato; comprovante final.","insufficientEvidence":"Erro resolvido pelo suporte sem participação.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-MU-01","level":3,"text":"Cria roteiros utilizáveis","kind":"evidence","guidance":"Roteiros criados.","reviewCheck":"Colega opera usando o roteiro.","supportingEvidence":"Roteiro; relato do colega.","insufficientEvidence":"Roteiro desatualizado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-MU-02","level":3,"text":"Forma operadores","kind":"evidence","guidance":"Treinados.","reviewCheck":"Operam sozinhos.","supportingEvidence":"Comprovantes dos treinados.","insufficientEvidence":"Treinamento sem verificação.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F03-MU-03","level":3,"text":"Resolve problemas de plataforma","kind":"evidence","guidance":"Casos com suporte.","reviewCheck":"Resolvidos e documentados.","supportingEvidence":"Protocolo de suporte.","insufficientEvidence":"Caso sem registro.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não autoriza usar certificado digital ou credencial do cliente fora da finalidade autorizada.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F04', $${"code":"F04","nature":"Funcional","title":"Gestão de Obrigações e Condicionantes","summary":"Identificar as obrigações decorrentes de licenças, outorgas, TACs e cadastros (condicionantes, RAPP, TCFA, DMR, renovações, taxas), montar o calendário de cumprimento por cliente, acionar os setores e comprovar o atendimento.","originLabel":"Processos e Órgãos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de identificar as obrigações decorrentes de licenças, outorgas, TACs e cadastros (condicionantes, relatórios, taxas, declarações, renovações), montar o calendário de cumprimento por cliente, acionar os setores responsáveis e comprovar o atendimento perante o órgão.","scope":"• ler licenças, outorgas, TACs e termos e extrair as obrigações\r\n• classificar obrigações (documental, técnica, de campo, financeira)\r\n• montar o calendário de cumprimento por cliente\r\n• atribuir responsáveis e acionar os setores\r\n• acompanhar a execução\r\n• protocolar a comprovação do atendimento\r\n• controlar taxas e declarações periódicas\r\n• alertar o cliente sobre obrigações próprias","performanceCriteria":"• Extração sem omissão: todas as condicionantes e obrigações de cada licença, outorga, TAC ou cadastro são identificadas e registradas. Como se comprova: o avaliador lê o documento original e compara com a lista extraída pela pessoa.\r\n• Nada vence sem ação: cada obrigação tem responsável e data, e é cumprida ou tratada antes do vencimento. Como se comprova: cruzamento do calendário de obrigações com as datas reais de cumprimento.\r\n• Comprovação protocolada: o atendimento de cada obrigação é comprovado perante o órgão e o comprovante fica arquivado. Como se comprova: sorteio de obrigações cumpridas e busca pelo protocolo de comprovação.\r\n• Cliente ciente: o cliente sabe quais obrigações dependem dele e quando. Como se comprova: análise dos avisos enviados ao cliente.","assisted":"Consegue: manter um calendário de obrigações já montado.\r\nAinda necessita: validação da extração de obrigações.","autonomous":"Faz sozinho: extrai, controla e comprova obrigações de uma carteira.\r\nDecide: responsáveis, priorização e momento de comprovar.","multiplier":"Desenha a matriz de obrigações da Ramos, audita carteiras, trata TACs e casos complexos e forma a equipe.","certificationEvidence":"ASSISTIDO\r\nO que entregar: o calendário de obrigações de 1 cliente montado por você.\r\nComo é avaliado: o avaliador compara o calendário com as licenças e outorgas do cliente.\r\nAprovado quando: nenhuma obrigação foi esquecida e as datas estão corretas.\r\n\r\nAUTÔNOMO\r\nO que entregar: (1) a extração de obrigações de 3 licenças ou outorgas; (2) o histórico de 3 meses do controle de obrigações de uma carteira.\r\nComo é avaliado: comparação das extrações com os documentos originais e cruzamento do controle com os cumprimentos.\r\nAprovado quando: as 3 extrações estão completas e nenhuma obrigação venceu sem ação nos 3 meses.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) auditoria de carteiras de outros; (2) um modelo de matriz de obrigações; (3) registro de treinamento.\r\nComo é avaliado: a direção analisa a auditoria e verifica o uso da matriz pela equipe.\r\nAprovado quando: a auditoria encontrou falhas reais e a matriz foi adotada.","prerequisites":"Assistido: nenhum.\r\nAutônomo: T04 Gestão de Prazos e Prioridades — Autônomo.\r\nMultiplicador: F02 Gestão de Processos Regulatórios — Autônomo.","limits":"Não abrange produzir os relatórios técnicos de atendimento (F07) nem executar o monitoramento (E05/F10).","relatedCapabilitiesText":"T04 Gestão de Prazos e Prioridades · F02 Gestão de Processos Regulatórios · F03 Operação de Sistemas e Plataformas · F07 Produção Técnica Ambiental"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você consegue ler uma licença, outorga ou TAC e extrair todas as obrigações, prazos e periodicidades?","sourceRef":"Autoavaliação!A57:E57"},{"number":2,"dimension":"Execução","question":"Você monta e mantém o calendário de obrigações do cliente e aciona os responsáveis?","sourceRef":"Autoavaliação!A58:E58"},{"number":3,"dimension":"Julgamento e decisão","question":"Você decide prioridades, responsáveis e a forma de comprovação de cada obrigação?","sourceRef":"Autoavaliação!A59:E59"},{"number":4,"dimension":"Qualidade e consistência","question":"Todas as obrigações sob seu controle são cumpridas e comprovadas perante o órgão, sem vencimentos esquecidos?","sourceRef":"Autoavaliação!A60:E60"}],"sourceRefs":["Catálogo de Capacidades!A18:D18","Fichas de Capacidade!A18:P18"]}$$::jsonb, $$[{"id":"F04-AS-01","level":1,"text":"Mantém calendário atualizado","kind":"evidence","guidance":"Calendário × obrigações reais.","reviewCheck":"Sem obrigações faltando ou vencidas sem registro.","supportingEvidence":"Calendário.","insufficientEvidence":"Calendário completado para a avaliação.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-AS-02","level":1,"text":"Reconhece obrigações geradas","kind":"evidence","guidance":"Obrigações identificadas em cadastros/licenças.","reviewCheck":"Identificação correta e repasse.","supportingEvidence":"Registros de repasse.","insufficientEvidence":"Ignorar obrigações periódicas.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-AS-03","level":1,"text":"Interpreta o que a condicionante pede","kind":"evidence","guidance":"Conversa sobre condicionante real.","reviewCheck":"Explica exigência e prazo.","supportingEvidence":"Licença real.","insufficientEvidence":"Leitura literal sem entender.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-AU-01","level":2,"text":"Extrai obrigações completas","kind":"evidence","guidance":"Licença/TAC × obrigações extraídas.","reviewCheck":"Nenhuma obrigação omitida; classificação correta.","supportingEvidence":"Documento de origem; matriz.","insufficientEvidence":"Extração revisada integralmente por outro.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-AU-02","level":2,"text":"Aciona e acompanha a execução","kind":"evidence","guidance":"Acionamentos aos setores.","reviewCheck":"Executor informado com antecedência e cobrado.","supportingEvidence":"Cards; e-mails.","insufficientEvidence":"Acionar no vencimento.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-AU-03","level":2,"text":"Comprova no prazo","kind":"evidence","guidance":"Protocolos de comprovação.","reviewCheck":"Comprovação protocolada antes do prazo.","supportingEvidence":"Protocolos.","insufficientEvidence":"Executar sem comprovar ao órgão.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-MU-01","level":3,"text":"Estrutura a matriz em uso","kind":"evidence","guidance":"Matriz-modelo.","reviewCheck":"Adotada pelas carteiras.","supportingEvidence":"Matrizes.","insufficientEvidence":"Modelo não adotado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-MU-02","level":3,"text":"Audita carteiras","kind":"evidence","guidance":"Auditoria realizada.","reviewCheck":"Falhas reais tratadas.","supportingEvidence":"Relatório.","insufficientEvidence":"Auditoria sem achados.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F04-MU-03","level":3,"text":"Conduz casos complexos e forma","kind":"evidence","guidance":"Caso e orientados.","reviewCheck":"Caso resolvido; orientados autônomos.","supportingEvidence":"Registros.","insufficientEvidence":"Caso conduzido por outro.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F05', $${"code":"F05","nature":"Funcional","title":"Gestão Documental Regulatória","summary":"Elaborar e conferir ofícios, requerimentos, procurações, declarações e publicações legais, obter certidões, garantir a regularidade documental e montar o processo conforme a exigência do órgão.","originLabel":"Processos e Órgãos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de elaborar e conferir ofícios, requerimentos, procurações, declarações e publicações legais, obter certidões, garantir a regularidade documental do cliente e montar o processo exatamente conforme exigido pelo órgão.","scope":"• redigir ofícios, requerimentos, declarações e procurações\r\n• obter certidões e verificar validade\r\n• providenciar publicações legais (IOE e jornais)\r\n• montar o processo na ordem e no formato exigidos\r\n• conferir assinaturas, reconhecimentos e anexos\r\n• aplicar checklist documental por tipo de processo","performanceCriteria":"• Sem erro formal: ofícios, requerimentos, procurações e declarações saem com dados, assinaturas e formato corretos. Como se comprova: conferência de uma amostra de documentos com o checklist documental.\r\n• Certidões válidas: toda certidão anexada está dentro da validade na data do protocolo. Como se comprova: verificação das datas de emissão e de validade nos processos protocolados.\r\n• Publicações no prazo: as publicações legais (Diário Oficial, jornal) são feitas dentro do prazo exigido. Como se comprova: comparação entre a data da emissão da licença e a data da publicação.\r\n• Processo sem exigência documental: o processo é montado na ordem e com os documentos exigidos pelo órgão. Como se comprova: análise das exigências recebidas e de sua causa.","assisted":"Consegue: elaborar documentos a partir de modelos.\r\nAinda necessita: conferência antes da assinatura e do protocolo.","autonomous":"Faz sozinho: elabora, confere e monta a documentação dos processos.\r\nDecide: quais documentos o processo exige.","multiplier":"Cria e mantém modelos documentais, revisa a documentação de outros e treina a equipe.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 5 documentos oficiais elaborados por você (ofício, requerimento, procuração, declaração).\r\nComo é avaliado: um Autônomo confere cada um antes do uso.\r\nAprovado quando: os 5 são aprovados sem correção relevante.\r\n\r\nAUTÔNOMO\r\nO que entregar: 3 processos montados por você e protocolados.\r\nComo é avaliado: análise das respostas do órgão.\r\nAprovado quando: nenhum dos 3 recebeu exigência de natureza documental.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) modelos de documentos criados; (2) revisões de documentação de colegas; (3) registro de treinamento.\r\nComo é avaliado: a direção verifica o uso dos modelos e o resultado dos processos revisados.\r\nAprovado quando: os modelos estão em uso e os processos revisados não tiveram exigência documental.","prerequisites":"Assistido: T05 Comunicação Profissional — Assistido.\r\nAutônomo: T01 Gestão de Informações e Acervo — Assistido.\r\nMultiplicador: Autônomo nesta capacidade há 6 meses.","limits":"Não substitui documentos que exijam advogado ou cartório. Não autoriza assinar em nome do cliente.","relatedCapabilitiesText":"F02 Gestão de Processos Regulatórios · F03 Operação de Sistemas e Plataformas · T01 Gestão de Informações e Acervo"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você sabe quais documentos, certidões e publicações cada tipo de processo exige e em que ordem?","sourceRef":"Autoavaliação!A61:E61"},{"number":2,"dimension":"Execução","question":"Você redige ofícios, requerimentos, declarações e procurações e obtém certidões e publicações legais?","sourceRef":"Autoavaliação!A62:E62"},{"number":3,"dimension":"Julgamento e decisão","question":"Você identifica quando um documento está vencido, incompleto ou inadequado e decide o que providenciar?","sourceRef":"Autoavaliação!A63:E63"},{"number":4,"dimension":"Qualidade e consistência","question":"Os processos que você monta são aceitos sem exigência documental?","sourceRef":"Autoavaliação!A64:E64"}],"sourceRefs":["Catálogo de Capacidades!A19:D19","Fichas de Capacidade!A19:P19"]}$$::jsonb, $$[{"id":"F05-AS-01","level":1,"text":"Dados corretos e modelo adequado","kind":"evidence","guidance":"Documentos elaborados.","reviewCheck":"Dados do cliente e do processo corretos; modelo certo.","supportingEvidence":"Documentos; conferência.","insufficientEvidence":"Reescrita pelo conferente.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-AS-02","level":1,"text":"Certidões válidas","kind":"evidence","guidance":"Certidões obtidas.","reviewCheck":"Válidas na data de uso.","supportingEvidence":"Certidões.","insufficientEvidence":"Certidão vencida.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-AS-03","level":1,"text":"Anexos e assinaturas completos","kind":"evidence","guidance":"Conjunto entregue.","reviewCheck":"Sem pendência de assinatura/anexo.","supportingEvidence":"Checklist documental.","insufficientEvidence":"Pendências descobertas no protocolo.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-AU-01","level":2,"text":"Define o conjunto documental","kind":"evidence","guidance":"Documentos exigidos × entregues.","reviewCheck":"Conjunto completo para o tipo de processo/órgão.","supportingEvidence":"Processo; checklist.","insufficientEvidence":"Lista copiada sem verificar o órgão.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-AU-02","level":2,"text":"Sem exigência por falha documental","kind":"evidence","guidance":"Retorno do órgão.","reviewCheck":"Sem exigência documental evitável.","supportingEvidence":"Histórico do processo.","insufficientEvidence":"Poucos processos.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-AU-03","level":2,"text":"Publicações no prazo e formato","kind":"evidence","guidance":"Publicações providenciadas.","reviewCheck":"No prazo legal e no formato exigido.","supportingEvidence":"Comprovantes.","insufficientEvidence":"Publicação feita por outro.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-MU-01","level":3,"text":"Modelos e checklists em uso","kind":"evidence","guidance":"Modelos mantidos.","reviewCheck":"Atualizados e usados.","supportingEvidence":"Biblioteca.","insufficientEvidence":"Modelo obsoleto.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-MU-02","level":3,"text":"Revisão que evita exigências","kind":"evidence","guidance":"Revisões feitas.","reviewCheck":"Apontamentos relevantes.","supportingEvidence":"Registros.","insufficientEvidence":"Revisão superficial.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F05-MU-03","level":3,"text":"Forma a equipe","kind":"evidence","guidance":"Orientados.","reviewCheck":"Autônomos.","supportingEvidence":"Certificações.","insufficientEvidence":"Lista de presença.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não substitui documentos que exijam advogado ou cartório nem autoriza assinar em nome do cliente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F06', $${"code":"F06","nature":"Funcional","title":"Comunicação Institucional com Órgãos","summary":"Interagir com órgãos e analistas (consultas, reuniões, vistas, diligências, fiscalizações), obter informações, esclarecer exigências e sustentar tecnicamente a posição do cliente.","originLabel":"Processos e Órgãos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de interagir com órgãos e analistas — consultas, reuniões, vistas, diligências e fiscalizações —, obter informações, esclarecer exigências e sustentar tecnicamente a posição do cliente de forma respeitosa, registrada e eficaz.","scope":"• preparar e conduzir consultas técnicas\r\n• agendar e conduzir reuniões com analistas\r\n• solicitar vistas de processos e informações\r\n• realizar diligências presenciais\r\n• acompanhar fiscalizações in loco\r\n• registrar o que foi tratado em cada contato\r\n• sustentar argumentos técnicos\r\n• manter relacionamento institucional","performanceCriteria":"• Interação preparada: antes de contatar o órgão, a pessoa define o objetivo, reúne o histórico do processo e prepara as perguntas ou argumentos. Como se comprova: o avaliador pede o roteiro ou as anotações de preparação de interações recentes.\r\n• Registro de todo contato: cada consulta, reunião, vista ou diligência fica registrada com data, interlocutor, o que foi tratado e o próximo passo. Como se comprova: conferência dos registros no SISRAMOS ou no acervo do cliente.\r\n• Resultado efetivo: o contato com o órgão esclarece a exigência ou destrava o processo. Como se comprova: análise do andamento do processo depois da interação.\r\n• Postura institucional: a pessoa se comporta de forma respeitosa e técnica, preservando a imagem da Ramos e do cliente. Como se comprova: observação direta pelo avaliador em pelo menos uma interação.","assisted":"Consegue: acompanhar interações conduzidas por outra pessoa e fazer contatos simples (andamento).\r\nAinda necessita: preparação e condução por alguém mais experiente.","autonomous":"Faz sozinho: conduz consultas, reuniões e diligências normais.\r\nDecide: o que perguntar e argumentar dentro da posição definida para o cliente.","multiplier":"Conduz negociações técnicas e situações sensíveis (autuações, indeferimentos), orienta a equipe e mantém o relacionamento institucional.","certificationEvidence":"ASSISTIDO\r\nO que entregar: o registro de 3 interações com órgãos que você acompanhou, conduzidas por um colega mais experiente.\r\nComo é avaliado: o colega confere se os registros estão completos e conversa sobre o que você observou.\r\nAprovado quando: os 3 registros estão completos e você consegue explicar o objetivo e o resultado de cada interação.\r\n\r\nAUTÔNOMO\r\nO que entregar: o registro de 3 interações conduzidas por você (consulta, reunião ou diligência), com preparação, registro e resultado.\r\nComo é avaliado: o avaliador acompanha pelo menos 1 das interações e analisa o andamento dos processos depois delas.\r\nAprovado quando: as 3 foram bem preparadas e registradas e trouxeram esclarecimento ou avanço no processo.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) relato de um caso sensível conduzido por você (autuação, indeferimento ou negociação técnica); (2) registro de orientação a colegas.\r\nComo é avaliado: a direção analisa o caso e conversa com os orientados.\r\nAprovado quando: o caso teve desfecho favorável ou controlado e os orientados passaram a conduzir interações sozinhos.","prerequisites":"Assistido: T05 Comunicação Profissional — Assistido.\r\nAutônomo: T05 Comunicação Profissional — Autônomo e F02 Gestão de Processos Regulatórios — Assistido.\r\nMultiplicador: F02 Gestão de Processos Regulatórios — Autônomo.","limits":"Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","relatedCapabilitiesText":"T05 Comunicação Profissional · F02 Gestão de Processos Regulatórios · F10 Planejamento e Execução de Campo"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você entende o funcionamento do órgão, o papel do analista e o que precisa preparar antes de uma interação?","sourceRef":"Autoavaliação!A65:E65"},{"number":2,"dimension":"Execução","question":"Você conduz consultas, reuniões, vistas e diligências e registra o que foi tratado?","sourceRef":"Autoavaliação!A66:E66"},{"number":3,"dimension":"Julgamento e decisão","question":"Você consegue sustentar tecnicamente a posição do cliente e decidir o que pode ou não ser combinado na hora?","sourceRef":"Autoavaliação!A67:E67"},{"number":4,"dimension":"Qualidade e consistência","question":"Suas interações com órgãos esclarecem exigências e destravam processos, mantendo boa relação institucional?","sourceRef":"Autoavaliação!A68:E68"}],"sourceRefs":["Catálogo de Capacidades!A20:D20","Fichas de Capacidade!A20:P20"]}$$::jsonb, $$[{"id":"F06-AS-01","level":1,"text":"Registra o contato","kind":"evidence","guidance":"Registros.","reviewCheck":"O que foi tratado e encaminhamento.","supportingEvidence":"Cards.","insufficientEvidence":"Contato sem registro.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-AS-02","level":1,"text":"Postura adequada","kind":"evidence","guidance":"Relato do condutor.","reviewCheck":"Não antecipa posições.","supportingEvidence":"Relato.","insufficientEvidence":"Opinar tecnicamente sem autorização.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-AS-03","level":1,"text":"Repassa informações corretamente","kind":"evidence","guidance":"Repasse ao responsável.","reviewCheck":"Completo e rápido.","supportingEvidence":"Mensagens.","insufficientEvidence":"Repasse parcial.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-AU-01","level":2,"text":"Prepara a interação","kind":"evidence","guidance":"Preparo de reunião/consulta.","reviewCheck":"Objetivo e argumentos definidos.","supportingEvidence":"Pauta; notas.","insufficientEvidence":"Ir sem preparo.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-AU-02","level":2,"text":"Esclarece e sustenta posição","kind":"evidence","guidance":"Resultado da interação.","reviewCheck":"Exigência esclarecida; posição mantida com fundamento.","supportingEvidence":"Registro; resposta do órgão.","insufficientEvidence":"Concordar com tudo.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-AU-03","level":2,"text":"Registra e comunica","kind":"evidence","guidance":"Registro do contato.","reviewCheck":"Equipe e cliente informados.","supportingEvidence":"Cards; e-mails.","insufficientEvidence":"Sem registro.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-MU-01","level":3,"text":"Conduz situação sensível","kind":"evidence","guidance":"Caso real.","reviewCheck":"Desfecho favorável ou dano contido.","supportingEvidence":"Registros.","insufficientEvidence":"Caso conduzido por outro.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-MU-02","level":3,"text":"Orienta a equipe","kind":"evidence","guidance":"Orientados.","reviewCheck":"Conduzem interações sozinhos.","supportingEvidence":"Relato; registros.","insufficientEvidence":"Orientação pontual.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F06-MU-03","level":3,"text":"Preserva relacionamento","kind":"evidence","guidance":"Relato da equipe/cliente.","reviewCheck":"Canal institucional mantido.","supportingEvidence":"Histórico.","insufficientEvidence":"Impressão pessoal.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Não autoriza assumir compromissos em nome do cliente sem autorização nem representá-lo juridicamente.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F07', $${"code":"F07","nature":"Funcional","title":"Produção Técnica Ambiental","summary":"Elaborar estudos, planos, projetos, relatórios e memoriais ambientais (PCA, RCA, PGRS, PRAD, EIV, RIAA, relatórios de monitoramento etc.) com fundamento técnico e legal, no padrão Ramos. Estudos de impacto e planos de recuperação estão aqui, diferenciados pelo nível.","originLabel":"Projetos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de elaborar estudos, planos, projetos, relatórios e memoriais ambientais (PCA, RCA, RAC, PGRS, PGRCC, EIV, PEA, PRAD, RIAA, relatórios de monitoramento e de condicionantes) com fundamento técnico e legal, coerência entre dados, diagnóstico, conclusões e medidas propostas, no padrão Ramos.","scope":"• interpretar termo de referência e legislação aplicável\r\n• analisar dados e levantamentos\r\n• elaborar diagnóstico\r\n• identificar e avaliar impactos\r\n• propor medidas, programas e planos\r\n• redigir com coerência técnica\r\n• incorporar mapas, plantas, fotos e dados\r\n• aplicar os modelos Ramos\r\n• elaborar relatórios de monitoramento e de atendimento de condicionantes\r\n• conduzir ações de educação ambiental (palestras e treinamentos ao cliente)","performanceCriteria":"• Atendimento ao termo de referência: todos os itens exigidos pelo termo de referência ou pela norma aplicável estão presentes e desenvolvidos. Como se comprova: o revisor confere o documento item a item contra o termo de referência.\r\n• Coerência técnica: os dados sustentam o diagnóstico, o diagnóstico sustenta as conclusões e as medidas respondem aos impactos identificados. Como se comprova: o revisor percorre essa cadeia em cada capítulo.\r\n• Fundamentação legal correta: as leis, resoluções e normas citadas são as vigentes e se aplicam ao caso. Como se comprova: conferência das referências legais pelo revisor.\r\n• Padrão Ramos: o documento usa o modelo, a estrutura e a formatação vigentes. Como se comprova: conferência com o checklist de padrão documental.\r\n• Aprovação na revisão interna: o documento passa pela revisão sem precisar de correção estrutural (refazer capítulos, refazer análises). Como se comprova: leitura do registro de revisão.\r\n• Aceitação pelo órgão: o documento é aceito sem exigência por deficiência técnica. Como se comprova: análise da resposta do órgão.","assisted":"Consegue: elaborar partes de documentos ou documentos simples a partir de modelos.\r\nAinda necessita: revisão integral.","autonomous":"Faz sozinho: elabora os estudos e relatórios usuais da Ramos, que passam por revisão normal.\r\nDecide: metodologia e conteúdo dentro do termo de referência.","multiplier":"Elabora estudos complexos (EIV, PRAD, estudos de impacto), orienta e revisa a produção de outros e aprimora os modelos.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 2 documentos técnicos (ou partes de um estudo) produzidos por você e revisados.\r\nComo é avaliado: o revisor registra o tipo e a quantidade de correções feitas.\r\nAprovado quando: as correções foram pontuais, e não estruturais, nos 2 documentos.\r\n\r\nAUTÔNOMO\r\nO que entregar: 3 produtos de tipos diferentes (ex.: PGRS, RCA e relatório de monitoramento) elaborados por você, com o registro de revisão e, em pelo menos 1 deles, a resposta do órgão.\r\nComo é avaliado: o revisor aplica os critérios de desempenho a cada produto e confere a resposta do órgão.\r\nAprovado quando: os 3 passaram na revisão sem correção estrutural e pelo menos 1 foi aceito pelo órgão sem exigência técnica.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) um estudo complexo elaborado por você (EIV, PRAD, estudo de impacto ou equivalente); (2) registro de orientação de produtores; (3) uma melhoria em modelo de documento.\r\nComo é avaliado: banca com a direção técnica e outro Multiplicador, que analisa o estudo, a orientação e a melhoria.\r\nAprovado quando: o estudo atende a todos os critérios, os orientados evoluíram e a melhoria está em uso.","prerequisites":"Assistido: nenhum.\r\nAutônomo: F09 Planejamento Técnico — Assistido.\r\nMultiplicador: F08 Revisão e Qualidade Técnica — Autônomo.","limits":"Restrita às áreas compatíveis com a formação e atribuição profissional. Não substitui ART nem responsável técnico habilitado. Dimensionamento de sistemas de engenharia está em E01.","relatedCapabilitiesText":"F08 Revisão e Qualidade Técnica · F09 Planejamento Técnico · E03 Modelagem e Representação Técnica · F04 Gestão de Obrigações e Condicionantes"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você consegue interpretar o termo de referência, a legislação aplicável e os dados disponíveis para o estudo ou relatório?","sourceRef":"Autoavaliação!A69:E69"},{"number":2,"dimension":"Execução","question":"Você elabora diagnóstico, avaliação de impactos, medidas e relatórios no modelo Ramos?","sourceRef":"Autoavaliação!A70:E70"},{"number":3,"dimension":"Julgamento e decisão","question":"Você decide metodologia, conteúdo e conclusões com fundamento técnico e legal?","sourceRef":"Autoavaliação!A71:E71"},{"number":4,"dimension":"Qualidade e consistência","question":"Seus produtos passam pela revisão sem correções estruturais e são aceitos pelo órgão sem exigência técnica?","sourceRef":"Autoavaliação!A72:E72"}],"sourceRefs":["Catálogo de Capacidades!A21:D21","Fichas de Capacidade!A21:P21"]}$$::jsonb, $$[{"id":"F07-AS-01","level":1,"text":"Seções aproveitáveis","kind":"evidence","guidance":"Versões antes/depois da revisão.","reviewCheck":"Ajustes, não reescrita.","supportingEvidence":"Versões; apontamentos.","insufficientEvidence":"Reescrita integral.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-AS-02","level":1,"text":"Usa dados corretamente","kind":"evidence","guidance":"Dados incorporados.","reviewCheck":"Coerentes com levantamentos.","supportingEvidence":"Pacote de campo; documento.","insufficientEvidence":"Dados copiados sem conferência.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-AS-03","level":1,"text":"Aplica o modelo Ramos","kind":"evidence","guidance":"Estrutura do documento.","reviewCheck":"Modelo vigente aplicado.","supportingEvidence":"Documento.","insufficientEvidence":"Modelo antigo.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-AU-01","level":2,"text":"Coerência técnica e legal","kind":"evidence","guidance":"Leitura do documento.","reviewCheck":"Dados, diagnóstico, impactos e medidas coerentes; base legal correta.","supportingEvidence":"Documento; revisão.","insufficientEvidence":"Forma bonita sem coerência.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Quantidade de documentos: A definir. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-AU-02","level":2,"text":"Aprovado em revisão normal","kind":"evidence","guidance":"Apontamentos de revisão.","reviewCheck":"Ajustes pontuais, não estruturais.","supportingEvidence":"Registro de revisão.","insufficientEvidence":"Revisão integral.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-AU-03","level":2,"text":"Decide metodologia","kind":"evidence","guidance":"Metodologia adotada.","reviewCheck":"Justificada pelo TR e pelos dados.","supportingEvidence":"Documento; conversa.","insufficientEvidence":"Metodologia copiada.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"Por que esta metodologia para este caso?","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-AU-04","level":2,"text":"Respeita limites de atribuição","kind":"evidence","guidance":"Temas tratados.","reviewCheck":"Escalou o que exige RT ou outra formação.","supportingEvidence":"Relato; ART.","insufficientEvidence":"Assumir tema fora da formação.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-MU-01","level":3,"text":"Domina estudo complexo","kind":"evidence","guidance":"Estudo complexo.","reviewCheck":"Aprovado com fundamento.","supportingEvidence":"Documento; retorno do órgão.","insufficientEvidence":"Estudo usual.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-MU-02","level":3,"text":"Forma e revisa produtores","kind":"evidence","guidance":"Orientados.","reviewCheck":"Sobem de nível.","supportingEvidence":"Certificações; revisões.","insufficientEvidence":"Revisar sem orientar.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F07-MU-03","level":3,"text":"Aprimora modelos","kind":"evidence","guidance":"Modelos.","reviewCheck":"Em uso.","supportingEvidence":"Biblioteca.","insufficientEvidence":"Modelo não adotado.","reviewerAlert":"Excelência individual ou tempo de casa não bastam; exija impacto verificável sobre pessoas ou sobre o método. Restrita às áreas compatíveis com a formação e atribuição profissional; não substitui ART nem responsável técnico habilitado.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Multiplicador. NÃO COMPROVADO: não há demonstração prática deste critério."}]$$::jsonb, 'ed1f3c2ef1cb93717fdb0e45a920fe718b81dd2894bf72f722b8eb04797f395f'),
  ('F08', $${"code":"F08","nature":"Funcional","title":"Revisão e Qualidade Técnica","summary":"Revisar produtos técnicos (próprios, da equipe ou de terceiros), verificar consistência, conformidade legal e aderência ao padrão Ramos, gerir correções e validar antes da emissão.","originLabel":"Projetos","sourceVersion":"1.0 — out/2026","detail":{"statement":"Uma pessoa certificada nesta capacidade é capaz de revisar produtos técnicos da Ramos, identificar inconsistências, verificar conformidade com os requisitos aplicáveis, assegurar o padrão documental da empresa, orientar correções e liberar entregas dentro dos limites correspondentes ao seu nível de domínio.","scope":"• interpretar os requisitos do produto técnico\r\n• revisar a coerência entre dados, diagnóstico, conclusão e medidas propostas\r\n• identificar ausência ou inconsistência de informações\r\n• verificar atendimento aos padrões internos\r\n• controlar versão e correção\r\n• registrar apontamentos de revisão\r\n• decidir se a entrega está apta a seguir\r\n• orientar o executor sobre os ajustes necessários","performanceCriteria":"Resultado esperado: a entrega revisada sai tecnicamente coerente, completa, dentro do padrão Ramos e sem pendências que deveriam ter sido identificadas na revisão.\r\n• Identificação das inconsistências relevantes: o revisor encontra os problemas que importam (erros técnicos, legais, de dados ou de atendimento ao termo de referência), e não apenas detalhes de forma. Como se comprova: um Multiplicador faz uma revisão de controle da mesma entrega e compara os apontamentos.\r\n• Nenhuma liberação incompleta: o revisor não libera documento com informação faltante, anexo ausente ou item do termo de referência não atendido, mesmo sob pressão de prazo. Como se comprova: conferência da versão liberada contra o checklist de requisitos.\r\n• Correções compreensíveis: os apontamentos dizem onde está o problema, qual é e o que se espera, de modo que o executor corrige sem perguntar. Como se comprova: leitura dos apontamentos e consulta ao executor.\r\n• Padrão documental: a versão liberada segue o modelo, a formatação, as legendas e a nomenclatura vigentes. Como se comprova: conferência com o checklist de padrão Ramos.\r\n• Respeito à autoria técnica: o revisor não altera dados, cálculos ou conclusões sem justificativa registrada e alinhamento com o executor ou o responsável técnico. Como se comprova: comparação entre versões e leitura do registro de revisão.\r\n• Redução da reincidência: com o tempo, os mesmos erros deixam de aparecer nas entregas revisadas pela pessoa. Como se comprova: comparação dos apontamentos ao longo de 3 meses.","assisted":"Consegue: revisar com checklist.\r\nAinda necessita: validação da sua revisão por um revisor Autônomo ou Multiplicador.","autonomous":"Faz sozinho: revisa e libera entregas normais sem outra validação.\r\nDecide: se a entrega está apta, quais correções são obrigatórias.","multiplier":"Revisa entregas críticas, desenvolve revisores e aperfeiçoa o padrão de qualidade da Ramos.","certificationEvidence":"ASSISTIDO\r\nO que entregar: 3 revisões reais feitas por você com o checklist de revisão, cada uma com os apontamentos registrados.\r\nComo é avaliado: um revisor Autônomo refaz a revisão das 3 entregas e compara com os seus apontamentos.\r\nAprovado quando: o checklist foi aplicado por completo e, em pelo menos 2 das 3, nenhuma falha crítica ficou sem apontamento.\r\n\r\nAUTÔNOMO\r\nO que entregar: 5 revisões de entregas reais de complexidades diferentes, liberadas por você (pelo menos 2 tipos de produto e 1 de complexidade média ou alta), com versão recebida, versão liberada e apontamentos.\r\nComo é avaliado: um Multiplicador faz revisão de controle em 2 das 5 entregas e consulta o retorno de órgãos e clientes.\r\nAprovado quando: nenhuma falha crítica passou e nenhuma entrega foi devolvida por erro que a revisão deveria ter detectado.\r\n\r\nMULTIPLICADOR\r\nO que entregar: (1) a revisão de 1 entrega crítica; (2) o registro da formação de 1 revisor até o nível Assistido; (3) 1 melhoria implantada no padrão de qualidade (checklist, roteiro ou modelo).\r\nComo é avaliado: banca com a direção técnica e outro Multiplicador.\r\nAprovado quando: a entrega crítica não tem falha remanescente, o formando foi aprovado como Assistido e a melhoria está em uso.","prerequisites":"Assistido: F07 Produção Técnica Ambiental — Autônomo (no domínio revisado).\r\nAutônomo: F07 Produção Técnica Ambiental — Autônomo.\r\nMultiplicador: F07 Produção Técnica Ambiental — Autônomo e T09 Padronização e Melhoria de Métodos — Autônomo.","limits":"Permite revisar tecnicamente apenas produtos dentro dos domínios em que o profissional possui formação e competência compatíveis. Não substitui atribuições profissionais legalmente restritas nem a responsabilidade técnica exigida por conselho profissional.","relatedCapabilitiesText":"F07 Produção Técnica Ambiental · T09 Padronização e Melhoria de Métodos · T10 Formação e Supervisão de Pessoas"},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você consegue interpretar os requisitos do produto revisado (termo de referência, legislação e padrão Ramos)?","sourceRef":"Autoavaliação!A73:E73"},{"number":2,"dimension":"Execução","question":"Você revisa a coerência entre dados, diagnóstico, conclusões e medidas e registra apontamentos claros?","sourceRef":"Autoavaliação!A74:E74"},{"number":3,"dimension":"Julgamento e decisão","question":"Você decide se a entrega está apta a seguir e quais correções são obrigatórias?","sourceRef":"Autoavaliação!A75:E75"},{"number":4,"dimension":"Qualidade e consistência","question":"As entregas que você revisa saem sem falhas que deveriam ter sido identificadas, e os erros reincidem menos?","sourceRef":"Autoavaliação!A76:E76"}],"sourceRefs":["Catálogo de Capacidades!A22:D22","Fichas de Capacidade!A22:P22"]}$$::jsonb, $$[{"id":"F08-AS-01","level":1,"text":"Apontamentos pertinentes","kind":"evidence","guidance":"Revisões feitas.","reviewCheck":"Problemas relevantes identificados.","supportingEvidence":"Registros.","insufficientEvidence":"Apontamentos só de forma.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Só revisa tecnicamente produtos dentro de domínios compatíveis com sua formação; não substitui responsabilidade técnica legal.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F08-AS-02","level":1,"text":"Poucos itens perdidos","kind":"evidence","guidance":"Comparação com o validador.","reviewCheck":"Validador acrescenta pouco.","supportingEvidence":"Revisões.","insufficientEvidence":"Validador refaz.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Só revisa tecnicamente produtos dentro de domínios compatíveis com sua formação; não substitui responsabilidade técnica legal.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F08-AS-03","level":1,"text":"Revisa no próprio domínio","kind":"evidence","guidance":"Domínio revisado.","reviewCheck":"Compatível com seu nível de produção.","supportingEvidence":"Fichas; histórico.","insufficientEvidence":"Revisar fora do domínio.","reviewerAlert":"Revisão e orientação são esperadas neste nível; não exija autonomia. Reprove apenas se não houver execução prática real. Só revisa tecnicamente produtos dentro de domínios compatíveis com sua formação; não substitui responsabilidade técnica legal.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Assistido. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F08-AU-01","level":2,"text":"Detecta inconsistências de conteúdo","kind":"evidence","guidance":"Revisões.","reviewCheck":"Coerência dados-diagnóstico-medidas verificada.","supportingEvidence":"Apontamentos.","insufficientEvidence":"Só formatação.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Só revisa tecnicamente produtos dentro de domínios compatíveis com sua formação; não substitui responsabilidade técnica legal.","reviewQuestion":"","possibleDecisions":"APROVADO: critério demonstrado com fatos e evidência verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios de domínio, mas faltam registro ou detalhe para confirmar. PARCIALMENTE COMPROVADO: demonstrado só em parte dos casos ou com apoio acima do previsto para Autônomo. NÃO COMPROVADO: não há demonstração prática deste critério."},{"id":"F08-AU-02","level":2,"text":"Decide aptidão com critério","kind":"evidence","guidance":"Liberações e retenções.","reviewCheck":"Justificativa clara.","supportingEvidence":"Registros.","insufficientEvidence":"Liberar tudo.","reviewerAlert":"Confirme que a condução foi sem supervisão cotidiana; trabalho bem feito sob revisão integral corresponde a Assistido. Só revisa tecnicamente produtos dentro de domínios compatíveis com sua formação; não substitui responsabilidade técnica legal.","reviewQuestion":"","poss