  ('F22', $${"code":"F22","nature":"Funcional","title":"Benefícios, Parcerias e Qualidade de Vida","summary":"Orientar cadastro; tirar dúvidas; registrar solicitações e problemas.","originLabel":"Matriz de capacidades e competências — out/2026","sourceVersion":"RESPOSABILIDADES 6 — out/2026","detail":{"statement":"Responde pela gestão de benefícios e parcerias: levanta necessidades, negocia condições e acompanha adesão.","scope":"• Orientar cadastro\n• tirar dúvidas\n• registrar solicitações e problemas.","performanceCriteria":"• Executa a prática esperada neste nível. Como se comprova: Orientar cadastro; tirar dúvidas; registrar solicitações e problemas.\n• Atua com a autonomia compatível. Como se comprova: Decide apenas o encaminhamento das dúvidas.\n• Respeita os limites e produz resultado observável. Como se comprova: Não negocia nem altera benefícios.\n• Executa a prática esperada neste nível. Como se comprova: Levantar demandas; negociar com parceiros (ex.: farmácia); divulgar; acompanhar uso e satisfação.\n• Atua com a autonomia compatível. Como se comprova: Decide condições dentro da alçada aprovada.\n• Respeita os limites e produz resultado observável. Como se comprova: Contratos dependem de aprovação da direção; dados de saúde seguem a LGPD.\n• Executa a prática esperada neste nível. Como se comprova: Manter o programa de benefícios e reconhecimento; avaliar resultados; propor novos benefícios.\n• Atua com a autonomia compatível. Como se comprova: Propõe a política de benefícios à direção.\n• Respeita os limites e produz resultado observável. Como se comprova: Orçamento depende da direção.","assisted":"Divulga benefícios existentes e apoia colaboradores no cadastro e uso das plataformas.","autonomous":"Responde pela gestão de benefícios e parcerias: levanta necessidades, negocia condições e acompanha adesão.","multiplier":"É referência em qualidade de vida: desenha o programa de benefícios e reconhecimento e orienta gestores.","certificationEvidence":"Registros, entregas, controles ou resultados reais que permitam verificar a atuação relatada.","prerequisites":"Consulte a matriz de formação da competência.","limits":"Contratos dependem de aprovação da direção; dados de saúde seguem a LGPD.","relatedCapabilitiesText":""},"selfAssessmentQuestions":[{"number":1,"dimension":"Compreensão dos requisitos","question":"Você entende o que é esperado para atuar em Benefícios, Parcerias e Qualidade de Vida?","sourceRef":"RESPOSABILIDADES 6.xlsx"},{"number":2,"dimension":"Execução","question":"Você já executa na prática as atividades de Benefícios, Parcerias e Qualidade de Vida?","sourceRef":"RESPOSABILIDADES 6.xlsx"},{"number":3,"dimension":"Julgamento e decisão","question":"Você reconhece o que pode decidir e quando deve escalar uma situação?","sourceRef":"RESPOSABILIDADES 6.xlsx"},{"number":4,"dimension":"Qualidade e consistência","question":"Seus resultados já podem ser verificados em casos reais?","sourceRef":"RESPOSABILIDADES 6.xlsx"}]}$$::jsonb, $$[{"id":"F22-AS-01","level":1,"text":"Executa a prática esperada neste nível","kind":"evidence","guidance":"Orientar cadastro; tirar dúvidas; registrar solicitações e problemas.","reviewCheck":"Colaboradores cadastrados; dúvidas respondidas ou encaminhadas.","supportingEvidence":"Entrega, registro ou resultado real relacionado ao caso relatado.","insufficientEvidence":"Relato sem registro verificável ou atividade executada integralmente por outra pessoa.","reviewerAlert":"Não negocia nem altera benefícios.","reviewQuestion":"Qual situação real demonstra essa atuação e onde ela pode ser verificada?","possibleDecisions":"APROVADO: prática real e verificável. COMPLEMENTAÇÃO NECESSÁRIA: há indícios, mas falta fato ou registro. NÃO COMPROVADO: não há demonstração prática."},{"id":"F22-AS-02","level":1,"text":"Atua com a autonomia compatível","kind":"evidence","guidance":"Decide apenas o encaminhamento das dúvidas.","reviewCheck":"Nível de entrada: já orienta o uso dos benefícios.","supportingEvidence":"Relato do caso, decisão tomada e registro da orientação ou escalonamento quando aplicável.","insufficientEvidence":"Atuação com supervisão acima do previsto para o nível solicitado.","reviewerAlert":"Não negocia nem altera benefícios.","reviewQuestion":"O que você decidiu, o que escalou e por quê?","possibleDecisions":"APROVADO: autonomia compatível. COMPLEMENTAÇÃO NECESSÁRIA: é preciso detalhar decisões. NÃO COMPROVADO: a autonomia não corresponde ao nível."},{"id":"F22-AS-03","level":1,"text":"Respeita os limites e produz resultado observável","kind":"evidence","guidance":"Não negocia nem altera benefícios.","reviewCheck":"Colaboradores cadastrados; dúvidas respondidas ou encaminhadas.","supportingEvidence":"Resultado entregue, controle atualizado ou confirmação verificável de quem recebeu a entrega.","insufficientEvidence":"Resultado alegado sem evidência ou atuação fora dos limites definidos.","reviewerAlert":"Não negocia nem altera benefícios.","reviewQuestion":"Qual foi o resultado verificável e como os limites do seu papel foram respeitados?","possibleDecisions":"APROVADO: resultado verificável e limites respeitados. COMPLEMENTAÇÃO NECESSÁRIA: falta evidência do resultado. NÃO COMPROVADO: resultado ou limites não foram demonstrados."},{"id":"F22-AU-01","level":2,"text":"Executa a prática esperada neste nível","kind":"evidence","guidance":"Levantar demandas; negociar com parceiros (ex.: farmácia); divulgar; acompanhar uso e satisfação.","reviewCheck":"Parcerias ativas com condições claras; adesão e satisfação acompanhadas.","supportingEvidence":"Entrega, registro ou resultado real relacionado ao caso relatado.","insufficientEvidence":"Relato sem registro verificável ou atividade executada integralmente por outra pessoa.","reviewerAlert":"Contratos dependem de aprovação da direção; dados de saúde seguem a LGPD.","reviewQuestion":"Qual situação real demonstra essa atuação e onde ela pode ser verificada?","possibleDecisions":"APROVADO: prática r